window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-1/eaif-3","titre":"EAIF III","sources":[{"t":"Chaînes musculaires","q":"chaines-musculaires/quiz.html","f":"chaines-musculaires/fiche.html"},{"t":"PNF — Facilitation neuromusculaire proprioceptive","q":"pnf/quiz.html","f":"pnf/fiche.html"},{"t":"Rééducation posturale globale","q":"reeducation-posturale/quiz.html","f":"reeducation-posturale/fiche.html"},{"t":"Santé au travail","q":"sante-au-travail/quiz.html","f":"sante-au-travail/fiche.html"},{"t":"Stabilité du complexe articulaire de l'épaule","q":"stabilite-epaule/quiz.html","f":"stabilite-epaule/fiche.html"},{"t":"Stabilité du complexe lombo-pelvi-fémoral","q":"stabilite-lombaire/quiz.html","f":"stabilite-lombaire/fiche.html"}],"questions":[{"q":"Qui parle pour la première fois de chaîne musculaire ?","o":["Madame Mézières","Philippe Souchard","Léopold Busquet","Tom Myers"],"r":0,"e":"Elle affirme que « toutes les déviations musculaires sont causées par la lordose » et parle du MOI comme être bio-psycho-social.","s":0},{"q":"Qui a créé la méthode de RPG ?","o":["Philippe Souchard","Madame Mézières","Godelieve Denys-Struyf","Tom Myers"],"r":0,"e":"Il utilise des étirements globaux impliquant tous les groupes musculaires du corps.","s":0},{"q":"Qui a créé les méridiens myofasciaux (trains anatomiques) ?","o":["Tom Myers","Léopold Busquet","Philippe Souchard","Madame Mézières"],"r":0,"e":"Par l'étude des voies fasciales.","s":0},{"q":"Quel est l'ordre hiérarchique des trois lois des chaînes musculaires ?","o":["Équilibre, économie, confort","Confort, équilibre, économie","Économie, confort, équilibre","Confort, économie, équilibre"],"r":0,"e":"Cette hiérarchie doit être respectée dans l'analyse de la statique.","s":0},{"q":"Quels systèmes assurent la loi de l'équilibre ?","o":["Le système nerveux sympathique et le système proprioceptif","Le système parasympathique et le système visuel","Le système vestibulaire seul","Le système musculaire seul"],"r":0,"e":"Le sympathique régule l'équilibre biologique, le proprioceptif l'équilibre de la verticalité.","s":0},{"q":"Quel muscle assure la loi de l'économie ?","o":["Le diaphragme","Le psoas","Le transverse de l'abdomen","Le carré des lombes"],"r":0,"e":"Il travaille constamment et de façon économique.","s":0},{"q":"Qu'est-ce qu'une contracture primaire ?","o":["La nouvelle posture adoptée pour éviter la souffrance, au prix d'une dépense d'énergie accrue","Une contracture musculaire aiguë","Une rétraction tendineuse","Un spasme réflexe"],"r":0,"e":"Un ajustement à la contracture primaire détermine ensuite une contracture secondaire.","s":0},{"q":"Quel est le rôle du diaphragme dans les chaînes musculaires ?","o":["Il est le point de convergence et d'union de toutes les chaînes","Il n'intervient que dans la respiration","Il appartient uniquement à la chaîne de flexion","Il n'a aucun rôle postural"],"r":0,"e":"Il fonctionne de manière permanente et est essentiel dans sa relation avec toutes les fonctions corporelles.","s":0},{"q":"À quel niveau l'aorte traverse-t-elle le diaphragme ?","o":["T12","T9","T10","T8"],"r":0,"e":"Veine cave à T9, œsophage à T10, aorte à T12.","s":0},{"q":"À quel niveau la veine cave traverse-t-elle le diaphragme ?","o":["T9","T10","T12","T7"],"r":0,"e":"Son orifice est une pseudo-valve qui module la projection horizontale.","s":0},{"q":"À quel niveau l'œsophage traverse-t-il le diaphragme ?","o":["T10","T9","T12","L1"],"r":0,"e":"L'orifice œsophagien est à gauche, essentiellement musculaire, avec une fonction proprioceptive et quantitative.","s":0},{"q":"Pourquoi l'orifice de l'aorte est-il fibreux et non élastique ?","o":["Pour ne pas perturber le flux artériel","Pour permettre l'expansion de l'aorte","Pour amortir les chocs","Pour faciliter la torsion"],"r":0,"e":"L'aorte est aussi placée près de la ligne de gravité pour rester au centre lors des torsions.","s":0},{"q":"Quel effet a un diaphragme bloqué en inspiration sur la posture ?","o":["Une lordose cervicale accentuée pour le confort cardiaque","Une cyphose thoracique","Une rectitude lombaire","Aucun effet"],"r":0,"e":"Bloqué en expiration, la stimulation du muscle cardiaque ne se fait pas, avec dépôt de graisse dans les coronaires.","s":0},{"q":"Qu'est-ce que la membrane de Laimer ?","o":["Un cordon rempli de tissu graisseux évitant l'échauffement mécanique de l'orifice œsophagien","Un ligament vertébral","Un fascia thoraco-lombaire","Une aponévrose diaphragmatique"],"r":0,"e":"Elle protège la zone de la descente et de la montée du diaphragme.","s":0},{"q":"Quelle est l'origine du psoas majeur ?","o":["Corps et processus transverses de T12 à L5","Crête iliaque uniquement","12ᵉ côte et L1-L5","Sacrum et coccyx"],"r":0,"e":"Le psoas mineur a une origine plus restreinte aux corps et disques de T12 et L1 ; les deux s'insèrent sur le petit trochanter.","s":0},{"q":"Quel muscle contrôle la rotation du psoas sur les vertèbres (point fixe lombaire) ?","o":["Le grand dorsal controlatéral","Le carré des lombes homolatéral","Le grand fessier","Le transverse de l'abdomen"],"r":0,"e":"Il agit via une contre-rotation.","s":0},{"q":"Que fait le psoas en point fixe fémoral ?","o":["Il lordose la colonne lombaire avec flexion latérale de son côté et rotation vers la convexité","Il cyphose la colonne lombaire","Il n'a aucune action sur la colonne","Il fléchit le tronc en avant"],"r":0,"e":"Cela survient quand on prend appui au sol avec besoin de verticalité et de rééquilibre.","s":0},{"q":"Quelle est l'action du carré des lombes ?","o":["Flexion latérale, fixation de la 12ᵉ côte et aide à l'expiration","Flexion du tronc","Rotation de la hanche","Extension cervicale"],"r":0,"e":"Ses fibres droites appartiennent à une chaîne d'extension, ses fibres obliques au système croisé.","s":0},{"q":"Que protège la ligne blanche sous-ombilicale ?","o":["Les organes du petit bassin des variations de pression","Le diaphragme","Le foie","L'estomac"],"r":0,"e":"Elle est très fermée et renforcée par les muscles droit et transverse de l'abdomen.","s":0},{"q":"Quels muscles favorisent la diastase sus-ombilicale ?","o":["Les rhomboïdes et le grand dentelé","Le droit de l'abdomen","Le transverse de l'abdomen","Le carré des lombes"],"r":0,"e":"Quand la diastase épuise sa capacité physiologique d'écartement, le droit de l'abdomen entre en action.","s":0},{"q":"Par où passe la ligne de gravité au niveau du crâne ?","o":["Par le foramen magnum, avec 2/3 du poids de la tête en avant","Par le vertex","Par l'os frontal","Par la protubérance occipitale externe"],"r":0,"e":"Au niveau plantaire elle passe en avant de la cheville : le résultat est un déséquilibre antérieur.","s":0},{"q":"Pourquoi le déséquilibre antérieur est-il physiologiquement utile ?","o":["Il constitue un premier pas contre l'inertie en faveur de la marche","Il économise le tissu osseux","Il protège les viscères","Il diminue la lordose"],"r":0,"e":"Dans un équilibre parfait, les centres d'équilibre seraient constamment en alerte, ce qui mènerait à l'épuisement.","s":0},{"q":"Pourquoi les muscles ne conviennent-ils pas à la fonction statique ?","o":["Un muscle qui travaille sans arrêt se fibrose et s'atrophie, en dépensant beaucoup d'énergie","Ils sont trop faibles","Ils manquent d'innervation","Ils ne résistent pas à la gravité"],"r":0,"e":"L'os, par sa structure alvéolaire et sa plasticité, et le tissu conjonctif sont mieux adaptés.","s":0},{"q":"Que fait le côlon transverse face aux forces descendantes du diaphragme ?","o":["Il réagit par une contre-force vers le haut, s'étendant et écartant les côtes inférieures","Il se comprime sans réaction","Il descend avec le diaphragme","Il se vide"],"r":0,"e":"C'est un élément clé de l'appui hydropneumatique abdominal.","s":0},{"q":"Quelle est la relation entre lordose lombaire et petit bassin ?","o":["La lordose protège les organes du petit bassin, et leur confort influence son degré","La lordose n'a aucun rapport avec le petit bassin","La lordose comprime les organes pelviens","Le petit bassin détermine la cyphose thoracique"],"r":0,"e":"Les forces exercées par le diaphragme se reflètent à travers les ailes iliaques.","s":0},{"q":"Où commence et où se termine la chaîne posturale ?","o":["Des fosses nasales à l'extrémité des orteils","De l'occiput au sacrum","Du sternum aux genoux","Du crâne aux mains"],"r":0,"e":"Elle est la structure conjonctive la plus étendue du plan postérieur.","s":0},{"q":"Quelle vertèbre organise la flexion sans être incluse dans le mouvement ?","o":["L3","L5","T12","S1"],"r":0,"e":"Au-dessus de L3 le thorax s'incline vers l'avant, en dessous le bassin se postériorise.","s":0},{"q":"Quel est le point fixe commun du système musculaire reliant colonne cervicale, ceinture scapulaire et membre supérieur ?","o":["L'apophyse coracoïde","L'acromion","Le manubrium sternal","L'épine de la scapula"],"r":0,"e":"C'est ce qui permet au système droit d'être accompagné en haut du corps.","s":0},{"q":"Quel est le centre de convergence de la chaîne croisée antérieure ?","o":["Le nombril","L3","Le sternum","Le pubis"],"r":0,"e":"La chaîne croisée postérieure a L3 comme centre de convergence.","s":0},{"q":"Comment travaillent les chaînes croisées et les systèmes de flexion/extension ?","o":["De façon complémentaire et non antagoniste","De façon strictement antagoniste","De façon indépendante","En alternance stricte"],"r":0,"e":"Les chaînes croisées ont besoin des systèmes de flexion et d'extension pour assurer la stabilité et la statique.","s":0},{"q":"Madame Mézières décrit le MOI comme :","o":["Un être purement biomécanique","Un être bio-psycho-social","Une somme de segments","Un système nerveux"],"r":1,"e":"Elle est la première à parler de chaîne musculaire, avec la formule « toutes les déviations musculaires sont causées par la lordose ».","s":0},{"q":"Godelieve Denys-Struyf a développé :","o":["La méthode de RPG","Une méthode personnalisée de correction et réorganisation du geste","Les méridiens myofasciaux","La méthode PNF"],"r":1,"e":"Sa question directrice : comment utilisons-nous le corps dans les différents mouvements de la vie quotidienne ?","s":0},{"q":"Léopold Busquet défend l'idée que :","o":["La lordose est la cause de tout","Un bon équilibre est indispensable à une bonne posture et à la liberté de mouvements","Les fascias forment des trains anatomiques","L'étirement doit être analytique"],"r":1,"e":"Tom Myers est l'auteur des méridiens myofasciaux, issus de l'étude des voies fasciales ; Souchard, celui de la RPG.","s":0},{"q":"Parmi les principes fondamentaux d'une chaîne musculaire, le cours cite :","o":["S'étendre de la tête aux pieds, intégrer tous les muscles du corps et ne présenter aucune faille","Se limiter à un membre","N'inclure que les muscles superficiels","Fonctionner indépendamment des autres chaînes"],"r":0,"e":"Une chaîne doit en outre obéir aux trois lois hiérarchisées : équilibre, économie, confort.","s":0},{"q":"Dans la loi de l'équilibre, le système proprioceptif régule :","o":["L'équilibre biologique des fonctions","L'équilibre de la verticalité","La dépense énergétique","Le confort"],"r":1,"e":"Le système nerveux sympathique régule, lui, l'équilibre biologique de toutes les fonctions. Les deux se partagent la première loi.","s":0},{"q":"La loi du confort énonce que l'homme cherche à vivre dans le confort :","o":["Sans coût énergétique","Même si cela entraîne une dépense supplémentaire d'énergie","Uniquement au repos","Uniquement en cas de douleur"],"r":1,"e":"C'est la troisième et dernière loi dans l'ordre hiérarchique : équilibre d'abord, économie ensuite, confort en dernier.","s":0},{"q":"La contracture secondaire résulte :","o":["D'un traumatisme direct","D'un ajustement à la contracture primaire pour répondre à l'exigence posturale","D'une carence musculaire","D'un défaut de croissance"],"r":1,"e":"Il se produit alors une inversion dans la hiérarchie de fonctionnement : la priorité devient le confort et l'absence de douleur.","s":0},{"q":"Les schémas de compensation aboutissent selon le cours :","o":["À une amélioration de la mobilité","À la douleur et à une déformation par fixation de tensions internes","À un renforcement musculaire","À une meilleure économie"],"r":1,"e":"Le besoin de confort est alors satisfait au prix d'une dépense énergétique accrue, d'une fatigue supplémentaire et d'un travail diaphragmatique majoré.","s":0},{"q":"Le diaphragme est constitué de fibres musculaires :","o":["Longitudinales parallèles","Semi-circulaires convergeant radialement vers le centre phrénique","Obliques croisées","Circulaires concentriques"],"r":1,"e":"Il exerce, à travers le tissu conjonctif, une action jusqu'à la périphérie — ce qui fonde son statut de carrefour de toutes les chaînes.","s":0},{"q":"L'orifice de la veine cave au niveau T9 comporte :","o":["Une structure fibreuse rigide","Une pseudo-valve qui module sa projection horizontale","Un sphincter musculaire","Aucune structure particulière"],"r":1,"e":"La montée du sang veineux s'en trouve facilitée à l'inspiration et freinée à l'expiration : le diaphragme agit comme une pompe veineuse.","s":0},{"q":"L'orifice œsophagien, situé à T10, est :","o":["Fibreux et rigide","Essentiellement musculaire, à fonction proprioceptive et quantitative","Dépourvu de contrôle","Situé à droite"],"r":1,"e":"Il se trouve à gauche et sa fonction est d'éviter les régurgitations, ce que sa nature musculaire rend possible.","s":0},{"q":"Au repos, la respiration implique :","o":["Le seul travail du diaphragme","Le diaphragme et les intercostaux","Tous les muscles accessoires","Les scalènes principalement"],"r":0,"e":"Le recrutement accessoire — sterno-cléido-occipito-mastoïdien, scalènes, pectoraux, rhomboïdes, grand dentelé — n'intervient qu'à l'effort ou en pathologie.","s":0},{"q":"La ligne de gravité passe par le foramen magnum avec une répartition du poids de la tête de :","o":["Moitié avant, moitié arrière","Deux tiers en avant, un tiers en arrière","Un tiers en avant, deux tiers en arrière","Totalement en avant"],"r":1,"e":"Elle passe également en avant de la cheville, ce qui crée un déséquilibre antérieur permanent que la musculature postérieure doit compenser.","s":0},{"q":"La vertèbre L3 se caractérise, dans l'organisation de la flexion, par le fait :","o":["Qu'elle est le sommet de la flexion","Que le mouvement s'organise autour d'elle sans qu'elle y soit incluse","Qu'elle est immobile","Qu'elle initie la flexion"],"r":1,"e":"Elle constitue par ailleurs le centre de convergence de la chaîne croisée postérieure, le nombril étant celui de la chaîne croisée antérieure.","s":0},{"q":"Le centre de convergence de la chaîne croisée antérieure se situe :","o":["En L3","Au nombril","Au sternum","Au pubis"],"r":1,"e":"Cette organisation croisée rend compte des schémas de torsion du tronc, où l'épaule d'un côté se relie à la hanche opposée.","s":0},{"q":"L'orifice aortique est fibreux et non élastique afin :","o":["De renforcer le diaphragme","De ne pas perturber le flux artériel","De permettre la régurgitation","De faciliter la digestion"],"r":1,"e":"L'aorte est en outre plaquée contre la colonne, près de la ligne de gravité, ce qui la maintient au centre lors des mouvements de torsion.","s":0},{"q":"L'œsophage adhère intimement à la colonne :","o":["Du processus basilaire de l'occipital jusqu'à T3","De C1 à C7","De T3 à T12","Uniquement au niveau du diaphragme"],"r":0,"e":"Cette adhérence explique les relations entre posture cervicale haute et troubles fonctionnels digestifs, souvent négligées en pratique.","s":0},{"q":"L'équilibre postural désigne le maintien de la position du corps :","o":["Au repos","En mouvement","Dans les deux cas indifféremment","Uniquement debout"],"r":0,"e":"L'équilibre dynamique concerne le maintien de la stabilité en mouvement. Les deux relèvent du même processus général de stabilité posturale.","s":0},{"q":"Selon la loi de l'économie, le muscle qui travaille constamment et de façon économique est :","o":["Le transverse de l'abdomen","Le diaphragme","Le multifidus","Le grand dorsal"],"r":1,"e":"Toutes les fonctions physiologiques sont réalisées avec une dépense d'énergie contrôlée et régulée par ce muscle, actif en permanence.","s":0},{"q":"À l'inspiration, l'estomac :","o":["Se verticalise","Est soumis à des pressions et s'horizontalise","Reste immobile","Se vide"],"r":1,"e":"À l'expiration, le relâchement du mésocôlon le replace dans une position plus verticale : la respiration mobilise donc mécaniquement les viscères.","s":0},{"q":"Que signifie PNF ?","o":["Facilitation Neuromusculaire Proprioceptive","Programme Neuro-Fonctionnel","Physiothérapie Neuro-Fasciale","Protocole Neuromusculaire Fonctionnel"],"r":0,"e":"C'est un système de promotion de la réponse des mécanismes neuromusculaires par stimulation des propriocepteurs.","s":1},{"q":"Qui sont les fondateurs du PNF entre 1945 et 1951 ?","o":["Le Dr Herman Kabat et la kinésithérapeute Margaret Knott","Voss et Bobath","Souchard et Mézières","Carr et Shepherd"],"r":0,"e":"En 1946, Voss et Knott écrivent le 1ᵉʳ livre sur le PNF.","s":1},{"q":"Comment définit-on la technique de PNF ?","o":["L'utilisation de stimuli spécifiques pour obtenir les réponses souhaitées, basées sur le mouvement normal","Un protocole d'étirement passif global","Une méthode de renforcement analytique","Une technique de mobilisation articulaire passive"],"r":0,"e":"Le kinésithérapeute facilite, à partir d'un input proprioceptif, sur le SNP et le SNC, vers une réponse musculaire.","s":1},{"q":"Le PNF peut-il être utilisé seul ?","o":["Oui, comme méthode unique ou en association","Non, jamais seul","Uniquement en association avec la RPG","Uniquement en post-opératoire"],"r":0,"e":"C'est une méthode de facilitation utilisable seule ou en association.","s":1},{"q":"Quel est l'objectif principal du PNF ?","o":["Faciliter au patient l'atteinte de son plus haut niveau fonctionnel","Renforcer uniquement les muscles faibles","Étirer les chaînes musculaires","Diminuer la spasticité"],"r":0,"e":"Il peut aussi présenter différents objectifs secondaires, et présuppose toujours une évaluation.","s":1},{"q":"Sur quoi le PNF se base-t-il ?","o":["La neurophysiologie, le contrôle moteur et l'apprentissage moteur","La biomécanique articulaire seule","L'anatomie fonctionnelle uniquement","La physiologie cardio-respiratoire"],"r":0,"e":"Ces trois bases guident la planification de l'intervention.","s":1},{"q":"Quelle est la direction du développement du contrôle moteur ?","o":["Cervico-caudale et proximo-distale","Caudo-cervicale et disto-proximale","Uniquement proximo-distale","Aléatoire"],"r":0,"e":"Il s'exprime de façon ordonnée par des schémas de mouvement.","s":1},{"q":"Quelle est la première phase du contrôle moteur ?","o":["La mobilité — assumer une posture et initier le mouvement","La stabilité","La stabilité dans la mobilité","Le skill"],"r":0,"e":"Puis stabilité, stabilité dans la mobilité, et skill.","s":1},{"q":"Que désigne la phase « stabilité dans la mobilité » ?","o":["Le mouvement contrôlé de A vers B","Le maintien d'une posture statique","Le mouvement dans toutes les directions","L'initiation du mouvement"],"r":0,"e":"La phase « skill » correspond aux segments qui se meuvent de façon contrôlée dans toutes les directions.","s":1},{"q":"Quelles sont les trois phases de l'apprentissage moteur ?","o":["Cognitive, associative, automatique","Mobilité, stabilité, skill","Préparation, action, correction","Initiation, exécution, correction"],"r":0,"e":"Elles se produisent à chaque phase du réapprentissage du contrôle moteur.","s":1},{"q":"Quel facteur conditionne principalement l'apprentissage moteur ?","o":["La répétition","La force développée","La vitesse d'exécution","L'amplitude articulaire"],"r":0,"e":"L'apprentissage moteur est un changement stable des comportements par acquisition de compétences via la pratique.","s":1},{"q":"Qu'est-ce que l'effet post-décharge ?","o":["L'effet d'un stimulus se poursuit après son interruption","La combinaison de stimuli successifs","La diffusion de la réponse vers d'autres muscles","L'inhibition des antagonistes"],"r":0,"e":"C'est l'un des six principes neurophysiologiques du PNF.","s":1},{"q":"Qu'est-ce que la sommation temporelle ?","o":["La succession de stimuli de basse fréquence dans un laps de temps, avec effet cumulatif","Des stimuli simultanés dans différentes zones","La propagation de la réponse au stimulus","L'excitation des antagonistes"],"r":0,"e":"La sommation spatiale concerne des stimuli simultanés dans différentes zones corporelles.","s":1},{"q":"Qu'est-ce que la sommation spatiale ?","o":["Des stimuli de basse intensité appliqués simultanément dans différentes zones se renforçant entre eux","La succession de stimuli dans le temps","L'effet persistant d'un stimulus","L'inhibition réciproque"],"r":0,"e":"Elle cause une excitation par renforcement mutuel des stimuli.","s":1},{"q":"Que permet l'irradiation ?","o":["Activer des groupes musculaires faibles en stimulant les groupes préservés, du proximal vers le distal","Inhiber les antagonistes","Prolonger l'effet du stimulus","Synchroniser les mouvements"],"r":0,"e":"Elle se caractérise par la diffusion et l'augmentation de la force de réponse.","s":1},{"q":"Qu'est-ce que l'innervation réciproque ?","o":["L'excitation des agonistes s'accompagne de l'inhibition des antagonistes","L'excitation des agonistes est suivie de celle des antagonistes","La diffusion de la réponse","L'effet cumulatif des stimuli"],"r":0,"e":"L'induction sélective/successive correspond au contraire à l'excitation des antagonistes après celle des agonistes.","s":1},{"q":"Que produit une contraction musculaire résistée ?","o":["Augmentation de la réponse du muscle, inhibition des antagonistes, stimulation proprioceptive et réponse des synergiques","Uniquement une augmentation de force","Uniquement une fatigue musculaire","Une inhibition des agonistes"],"r":0,"e":"C'est la chaîne d'effets de la résistance décrite dans le cours.","s":1},{"q":"Quelles précautions accompagnent l'application de la résistance ?","o":["Mouvement souple et coordonné, sans douleur ni fatigue indésirable, en évitant les apnées d'effort","Résistance toujours maximale","Résistance appliquée en apnée","Résistance appliquée uniquement en fin d'amplitude"],"r":0,"e":"Le choix entre résistance maximale et appropriée dépend de l'objectif, du patient et du type de contraction.","s":1},{"q":"Qu'est-ce que le renforcement en PNF ?","o":["Les groupes musculaires principaux potentialisent la force pour les accessoires agonistes","La propagation de l'influx nerveux","L'augmentation de la charge","L'ajout de séries supplémentaires"],"r":0,"e":"À distinguer de l'irradiation, qui est la propagation de la réponse d'influx nerveux.","s":1},{"q":"Que doit faire le contact manuel ?","o":["Informer le patient de la direction du mouvement et faciliter sa réalisation par le toucher et la pression","Immobiliser le segment","Remplacer la commande verbale","Empêcher tout mouvement"],"r":0,"e":"Il applique des stimuli proprioceptifs sur peau, muscles, ligaments, tendons et points-clés.","s":1},{"q":"Comment le thérapeute doit-il se positionner ?","o":["Épaules et hanches alignées dans la direction du mouvement, bras et mains alignés et relâchés","Perpendiculairement au mouvement","Toujours en fente latérale","Les bras verrouillés en extension"],"r":0,"e":"La résistance est la conséquence de la position du corps du thérapeute.","s":1},{"q":"Quels sont les trois temps de la commande verbale ?","o":["Préparation, action, correction","Explication, démonstration, exécution","Initiation, maintien, arrêt","Consigne, silence, feedback"],"r":0,"e":"Les instructions doivent être claires, concises et le ton de voix adapté au contexte.","s":1},{"q":"Quel est l'effet de la traction en PNF ?","o":["Elle facilite et oriente le mouvement et étire les tissus, par stimulation des récepteurs articulaires","Elle favorise la stabilité","Elle facilite la notion de charge","Elle inhibe la contraction"],"r":0,"e":"L'approximation, à l'inverse, favorise la stabilité et facilite la notion de charge.","s":1},{"q":"Quel est l'effet de l'approximation ?","o":["Elle favorise la stabilité et facilite la notion de charge et la contraction musculaire","Elle allonge le tronc","Elle étire les tissus","Elle diminue le tonus"],"r":0,"e":"Elle rapproche les fibres musculaires et stimule les récepteurs articulaires.","s":1},{"q":"Comment doit être appliqué l'étirement en PNF ?","o":["Rapide, subtil et léger sur le muscle sous tension, en débutant à l'amplitude d'étirement du schéma","Lent et prolongé","En fin d'amplitude uniquement","Sans résistance associée"],"r":0,"e":"Pour une plus grande efficacité, la contraction qui suit l'étirement doit être résistée.","s":1},{"q":"Combien de diagonales existe-t-il pour chaque partie du corps ?","o":["Deux","Une","Trois","Quatre"],"r":0,"e":"Pour chaque diagonale il existe deux schémas antagonistes : flexion et extension.","s":1},{"q":"Dans quels plans les schémas de PNF combinent-ils les mouvements ?","o":["Les trois plans : sagittal, frontal et transversal","Uniquement le plan sagittal","Uniquement les plans sagittal et frontal","Uniquement le plan transversal"],"r":0,"e":"Sagittal : flexion/extension ; frontal : abduction/adduction ; transversal : rotation.","s":1},{"q":"Quelle articulation est libre au sein d'un schéma de facilitation ?","o":["L'articulation intermédiaire","L'articulation proximale","L'articulation distale","Aucune"],"r":0,"e":"Les articulations proximales et distales sont liées au sein du schéma.","s":1},{"q":"À quelles composantes est associée la rotation externe dans un schéma ?","o":["Supination, déviation radiale et inversion","Pronation, déviation cubitale et éversion","Flexion et adduction","Extension et abduction"],"r":0,"e":"La rotation interne est associée à pronation, déviation cubitale et éversion.","s":1},{"q":"Quelle est la différence entre traitement direct et indirect en PNF ?","o":["Le direct porte sur le muscle ou membre lésé, l'indirect sur une zone moins lésée ou éloignée","Le direct est manuel, l'indirect verbal","Le direct est passif, l'indirect actif","Il n'y a pas de différence"],"r":0,"e":"Le traitement indirect met le focus sur la partie du corps la moins lésée.","s":1},{"q":"La phase « skill » du contrôle moteur correspond à :","o":["Assumer une posture et initier le mouvement","La stabilité dans la nouvelle position","Un mouvement contrôlé de A vers B","Des segments qui se meuvent de façon contrôlée dans toutes les directions"],"r":3,"e":"L'ordre complet : mobilité, stabilité, stabilité dans la mobilité, puis skill. Il faut évaluer où se situe le patient pour choisir la tâche et la position adéquates.","s":1},{"q":"Le développement du contrôle moteur suit une direction :","o":["Cervico-caudale et proximo-distale","Caudo-céphalique","Disto-proximale","Aléatoire"],"r":0,"e":"Postures et mouvements sont contrôlés par des commandes centrales et des réflexes spinaux, s'exprimant de façon ordonnée par des schémas de mouvement.","s":1},{"q":"La sommation spatiale se définit comme :","o":["Une succession de stimuli de basse fréquence dans le temps","Des stimuli de basse intensité appliqués simultanément en différentes zones corporelles, qui se renforcent entre eux","La poursuite d'un effet après l'arrêt du stimulus","La diffusion de la réponse vers d'autres groupes"],"r":1,"e":"La sommation temporelle concerne la succession dans le temps, l'effet post-décharge la persistance après interruption, l'irradiation la diffusion.","s":1},{"q":"L'irradiation permet, en pratique :","o":["D'activer des groupes musculaires faibles en stimulant les groupes préservés, du proximal vers le distal","D'inhiber les antagonistes","De prolonger l'effet du stimulus","D'alterner agonistes et antagonistes"],"r":0,"e":"C'est l'un des principes les plus exploités du PNF : recruter la force là où elle existe pour la faire diffuser là où elle manque.","s":1},{"q":"L'induction sélective ou successive signifie que :","o":["L'excitation des agonistes s'accompagne de l'inhibition des antagonistes","L'augmentation de l'excitation des agonistes est suivie de l'excitation de leurs antagonistes","Les stimuli s'additionnent dans le temps","La réponse persiste après le stimulus"],"r":1,"e":"C'est l'innervation réciproque qui décrit l'excitation des agonistes accompagnée de l'inhibition des antagonistes — deux principes distincts à ne pas confondre.","s":1},{"q":"La contraction résistée en PNF produit :","o":["Une inhibition des synergiques","Une augmentation de la réponse du muscle, une inhibition des antagonistes et une stimulation proprioceptive","Une fatigue recherchée","Une diminution du contrôle moteur"],"r":1,"e":"Elle augmente aussi la réponse des synergiques. Elle doit permettre un mouvement souple et coordonné, sans douleur ni fatigue indésirable.","s":1},{"q":"Concernant la respiration pendant la résistance, le cours recommande :","o":["Une apnée d'effort","D'éviter les apnées d'effort en favorisant une respiration contrôlée","Une hyperventilation","De ne pas s'en préoccuper"],"r":1,"e":"L'apnée d'effort élève la pression intrathoracique et expose à des conséquences cardiovasculaires, sans bénéfice pour la facilitation recherchée.","s":1},{"q":"La position du kinésithérapeute en PNF suppose :","o":["Des bras tendus et verrouillés","Des épaules et hanches alignées dans la direction du mouvement, bras et mains alignés et relativement relâchés","Une position fixe quel que soit le schéma","Un appui sur la table"],"r":1,"e":"La résistance est décrite comme la conséquence de la position du corps du thérapeute, et non comme un effort des bras.","s":1},{"q":"La commande verbale en PNF se structure en trois temps :","o":["Préparation, action, correction","Inspiration, contraction, expiration","Départ, maintien, retour","Écoute, exécution, évaluation"],"r":0,"e":"Les instructions doivent être claires et concises, avec un ton adapté, et répétées pour stimuler l'engagement ou rediriger le mouvement.","s":1},{"q":"La traction en PNF produit ses effets par :","o":["Rapprochement des surfaces articulaires","Allongement du tronc ou d'une extrémité, avec stimulation des récepteurs articulaires","Compression axiale","Vibration"],"r":1,"e":"Elle facilite et oriente le mouvement et étire les tissus. L'approximation, à l'inverse, rapproche les fibres et favorise la stabilité.","s":1},{"q":"L'approximation facilite :","o":["Le mouvement","La stabilité, la notion de charge et la contraction musculaire","L'étirement des tissus","La relaxation"],"r":1,"e":"Elle agit également par stimulation des récepteurs articulaires, mais dans un sens opposé à celui de la traction.","s":1},{"q":"Pour une efficacité maximale, la contraction qui suit l'étirement doit être :","o":["Libre","Résistée","Lente","Excentrique"],"r":1,"e":"Le mouvement doit débuter à l'amplitude d'étirement du schéma ; l'étirement peut être rapide, subtil et léger sur le muscle sous tension.","s":1},{"q":"L'étirement en PNF facilite :","o":["Uniquement le muscle allongé","Le muscle allongé, ceux de la même articulation et les synergiques","Les antagonistes","Les muscles distaux uniquement"],"r":1,"e":"Cette diffusion de l'effet facilitateur rejoint le principe d'irradiation, qui structure toute la méthode.","s":1},{"q":"Dans un schéma de facilitation, l'articulation intermédiaire :","o":["Est fixée dans le schéma","Est libre de réaliser flexion, extension ou de maintenir sa position initiale","Doit toujours être en flexion","Est exclue du mouvement"],"r":1,"e":"Les articulations proximales et distales du membre sont, elles, liées au sein du schéma. Modifier l'action de l'intermédiaire est l'une des variations possibles.","s":1},{"q":"Dans les composantes d'un schéma, le croisement de la ligne médiane correspond à :","o":["L'abduction","L'adduction","La rotation externe","L'extension"],"r":1,"e":"L'éloignement de la ligne médiane correspond à l'abduction. La rotation externe s'associe à supination, déviation radiale et inversion.","s":1},{"q":"La rotation interne, dans les schémas PNF, s'associe à :","o":["Supination, déviation radiale et inversion","Pronation, déviation cubitale et éversion","Flexion et adduction","Extension et abduction"],"r":1,"e":"Ces correspondances permettent de construire un schéma cohérent sur toute la longueur du membre, du proximal au distal.","s":1},{"q":"Parmi les variations possibles d'un schéma, le cours cite :","o":["Modifier la position du patient et les effets de la gravité","Changer de thérapeute","Augmenter le nombre de séances","Modifier la température de la pièce"],"r":0,"e":"S'y ajoutent la modification de l'articulation intermédiaire, de l'effet sur les biarticulaires, l'usage d'un input visuel différent et l'association à la fonction.","s":1},{"q":"Le traitement indirect en PNF consiste à :","o":["Travailler le muscle ou membre lésé","Se centrer sur une zone moins lésée ou éloignée","Ne pas intervenir","Utiliser uniquement la parole"],"r":1,"e":"Il exploite l'irradiation : stimuler une région préservée peut faciliter une région atteinte, sans la solliciter directement.","s":1},{"q":"Parmi les composantes clés de la technique, le cours cite :","o":["L'usage de séquences du distal vers le proximal","Un mouvement strictement dans le plan sagittal","L'absence de résistance","Un travail sans commande verbale"],"r":0,"e":"S'y ajoutent les schémas en diagonale croisant la ligne médiane, le recours aux réflexes, le recrutement d'agonistes et d'antagonistes et les contractions répétées.","s":1},{"q":"Le cours résume l'exigence de l'exercice en PNF par la formule :","o":["Mouvement sans effort","Mouvement sans douleur, mais avec effort","Effort maximal quelle que soit la douleur","Mouvement passif uniquement"],"r":1,"e":"L'effort est nécessaire à la facilitation, mais la douleur signalerait une inadéquation de la résistance, de l'amplitude ou du positionnement.","s":1},{"q":"Qui a créé la méthode de Rééducation Posturale Globale et en quelle année ?","o":["Ph. Souchard en 1980/1981","Madame Mézières en 1947","Léopold Busquet en 1990","Tom Myers en 2001"],"r":0,"e":"La RPG est le fondement théorico-pratique de la rééducation posturale enseignée en EAIF III.","s":2},{"q":"Quel principe affirme que la cause peut être anatomiquement éloignée du symptôme ?","o":["La causalité","L'individualité","La globalité","La progressivité"],"r":0,"e":"Les trois principes fondamentaux sont individualité, causalité et globalité.","s":2},{"q":"Que signifie le principe de globalité ?","o":["Le corps humain doit être traité comme un tout","Chaque muscle doit être traité isolément","Tous les patients réagissent de la même façon","Le symptôme doit être traité en premier"],"r":0,"e":"Il faut identifier les implications des rétractions musculaires dans les pathologies musculo-squelettiques.","s":2},{"q":"Quelle est la logique de la démarche en RPG ?","o":["Partir du symptôme pour atteindre la cause","Partir de la cause pour expliquer le symptôme","Traiter la maladie et non l'individu","Traiter uniquement le segment douloureux"],"r":0,"e":"On intervient sur l'individu et non sur la maladie ; évaluation et raisonnement clinique sont déterminants.","s":2},{"q":"Quelle fonction musculaire la méthode valorise-t-elle ?","o":["La fonction statique","La fonction dynamique","La fonction pliométrique","La fonction aérobie"],"r":0,"e":"Les muscles de la statique sont sollicités en permanence, ce qui favorise leur raccourcissement.","s":2},{"q":"Quel est l'objectif de la RPG ?","o":["Identifier et étirer les muscles responsables des signes et symptômes","Renforcer les muscles faibles de façon concentrique","Mobiliser les articulations bloquées","Diminuer le tonus par massage"],"r":0,"e":"Le raccourcissement des muscles statiques altère amplitude, qualité du mouvement et posture.","s":2},{"q":"Quel type de fibres prédomine dans les muscles de la statique ?","o":["Les fibres de type I","Les fibres de type II","Les fibres intermédiaires","Les fibres cardiaques"],"r":0,"e":"Ils sont très toniques, peu phasiques, avec des motoneurones alpha-toniques à décharge lente.","s":2},{"q":"Quelle caractéristique appartient aux muscles de la dynamique ?","o":["Rapidement fatigables, avec énergie produite par des processus anaérobies","Très résistants et peu fatigables","Très fibreux et riches en collagène","Fibres musculaires courtes"],"r":0,"e":"Les muscles statiques sont au contraire peu fatigables, avec un métabolisme aérobie.","s":2},{"q":"Quels muscles sont plus aptes à résister à l'étirement ?","o":["Les muscles de la statique","Les muscles de la dynamique","Les deux également","Aucun"],"r":0,"e":"Les muscles dynamiques sont plus aptes à réaliser le mouvement.","s":2},{"q":"Quel groupe assure la fonction statique d'érection ?","o":["Triceps sural, ischio-jambiers, pelvi-trochantériens, droit fémoral et spinaux","Scalènes et trapèze supérieur","Rotateurs internes et externes","Intercostaux et médiastin"],"r":0,"e":"Ce sont les muscles antigravitaires.","s":2},{"q":"Quel groupe assure la fonction statique de suspension ?","o":["Scalènes, trapèze supérieur, intercostaux et système musculo-fibreux médiastinal","Triceps sural et ischio-jambiers","Adducteurs et abducteurs","Spinaux et droit fémoral"],"r":0,"e":"Ils assurent la suspension de la ceinture scapulaire et du thorax.","s":2},{"q":"Comment doivent être renforcés les muscles de la statique selon la RPG ?","o":["Par contractions isométriques dans des positions progressivement excentriques","De façon concentrique à charge élevée","En course interne maximale","Par électrostimulation"],"r":0,"e":"Ils ne doivent jamais être renforcés de façon concentrique ; on combine mouvement actif et étirement.","s":2},{"q":"Que devient un muscle statique raide et raccourci ?","o":["Il perd la capacité de générer de la force","Il devient plus puissant","Il gagne en endurance","Il ne change pas fonctionnellement"],"r":0,"e":"Un muscle a plus de capacité à développer une contraction lorsqu'il est allongé.","s":2},{"q":"Quel est un exemple d'aponévrose d'intersection ?","o":["La ligne blanche abdominale","Le fascia lata","L'aponévrose plantaire","Le fascia thoraco-lombaire"],"r":0,"e":"Les aponévroses d'intersection correspondent au croisement de deux aponévroses.","s":2},{"q":"Quelle est la composition en collagène des tendons ?","o":["70 à 80 %","30 à 40 %","90 à 95 %","50 %"],"r":0,"e":"C'est ce qui les rend très résistants à l'étirement.","s":2},{"q":"Quel est le rôle des ligaments selon le cours ?","o":["Ils fonctionnent comme des freins articulaires","Ils assurent la coaptation articulaire","Ils permettent le glissement musculaire","Ils insèrent les muscles"],"r":0,"e":"Les capsules articulaires maintiennent la coaptation et servent d'insertion à certains muscles.","s":2},{"q":"Quelle est la conséquence d'une traction sur une extrémité d'une chaîne musculaire ?","o":["Elle se transmet le long de la chaîne et produit une compensation en un point quelconque","Elle reste locale","Elle étire uniquement le muscle tracté","Elle bloque l'articulation voisine"],"r":0,"e":"D'où la nécessité d'empêcher toutes les compensations pour obtenir l'étirement de la chaîne.","s":2},{"q":"Que comprend la chaîne maîtresse antérieure ?","o":["Le système de suspension cervico-thoraco-phrénique","Les spinaux et le triceps sural","Le fascia plantaire","Les rotateurs de hanche"],"r":0,"e":"Sa rétraction définit le type postural antérieur.","s":2},{"q":"Comment doivent travailler les antagonistes pour un mouvement normal ?","o":["En excentrique, pour contrôler le mouvement, tout en pouvant s'allonger","En concentrique uniquement","En isométrique uniquement","Ils ne doivent pas se contracter"],"r":0,"e":"Il faut renforcer les agonistes, étirer les antagonistes, et aussi renforcer les antagonistes de façon excentrique.","s":2},{"q":"Quels muscles assurent essentiellement la position debout ?","o":["Les muscles de la statique, toniques","Les muscles de la dynamique, phasiques","Les deux à parts égales","Les muscles respiratoires"],"r":0,"e":"Il ne devrait pas être nécessaire que les phasiques se contractent pour maintenir la posture.","s":2},{"q":"Qu'est-ce qu'un « muscle vainqueur » ?","o":["Le plus raide, qui exerce le plus de pression et impose le sens de la déformation","Le muscle le plus fort en concentrique","Le muscle le plus long","Le muscle le plus profond"],"r":0,"e":"Le « muscle vaincu » est le moins raide, qui cède à la raideur du vainqueur.","s":2},{"q":"Par quoi commence une rééducation morphologique correcte ?","o":["Par l'étirement des muscles les plus raccourcis, principaux responsables de la déformation","Par le renforcement des muscles vaincus","Par la mobilisation articulaire","Par le massage des muscles douloureux"],"r":0,"e":"Il faut rééquilibrer les groupes musculaires de la même typologie : vainqueurs et vaincus.","s":2},{"q":"Qu'est-ce que le réflexe myotatique direct ?","o":["La stimulation rapide du fuseau neuromusculaire provoque une contraction réflexe du muscle étiré","La contraction provoque un relâchement du muscle contracté","La contraction d'un agoniste inhibe l'antagoniste","La déformation permanente sous traction constante"],"r":0,"e":"Le réflexe myotatique inverse est celui où la contraction provoque un relâchement.","s":2},{"q":"Qu'est-ce que le fluage ?","o":["La déformation définitive d'un matériau soumis à une traction constante de durée suffisante","La contraction réflexe à l'étirement","L'inhibition de l'antagoniste","La perte d'élasticité par vieillissement"],"r":0,"e":"L'objectif est une réorganisation des chaînes macromoléculaires en position de plus grande longueur.","s":2},{"q":"Quelle est la position initiale d'une posture RPG ?","o":["Celle que le patient tolère sans effort et sans douleur","La position maximale d'étirement","La position anatomique stricte","La position antalgique du patient"],"r":0,"e":"Elle peut être très éloignée de la position normale exigée par la posture, du fait d'une incapacité anatomique et fonctionnelle.","s":2},{"q":"Quel allongement produit la traction manuelle passive ?","o":["Un millimètre au-delà du point d'inextensibilité","Cinq centimètres","Le maximum tolérable","Aucun allongement mesurable"],"r":0,"e":"C'est une traction sûre et sans risques pour le patient.","s":2},{"q":"Pourquoi la décoaptation est-elle nécessaire ?","o":["Parce que la rétraction musculaire augmente la coaptation articulaire","Pour diminuer la douleur uniquement","Pour accélérer la séance","Pour éviter le fluage"],"r":0,"e":"Elle doit être maintenue pendant toute la progression de la posture.","s":2},{"q":"Pourquoi la traction doit-elle être lente ?","o":["Pour éviter l'apparition du réflexe myotatique direct","Pour économiser l'énergie du thérapeute","Pour raccourcir la séance","Pour augmenter la force de tension"],"r":0,"e":"Le temps de traction augmente l'allongement obtenu et permet de diminuer la force de tension.","s":2},{"q":"Quelle est la durée maximale d'application d'une posture ?","o":["30 minutes","10 minutes","60 minutes","5 minutes"],"r":0,"e":"Avec des intervalles de repos, mais les pauses ne doivent pas être prolongées car contre-productives.","s":2},{"q":"Sur quoi reposent les étirements obtenus par les postures ?","o":["Un travail musculaire actif du patient combiné à la traction et à la décoaptation du kinésithérapeute","Une traction passive exclusive","Un relâchement complet du patient","Une contraction concentrique maximale"],"r":0,"e":"Le rythme est important et une manualité brusque est interdite.","s":2},{"q":"Le principe d'individualité en RPG implique :","o":["D'appliquer le même protocole à tous","De respecter l'individualité à tous les niveaux, notamment anatomo-physiologique","De traiter uniquement le symptôme","De standardiser les postures"],"r":1,"e":"Les trois principes fondamentaux sont individualité, causalité et globalité. Le cours résume la démarche : intervenir sur l'individu et non sur la maladie.","s":2},{"q":"La logique de la démarche en RPG consiste à :","o":["Partir de la cause pour atteindre le symptôme","Partir du symptôme pour atteindre la cause","Traiter uniquement la zone douloureuse","Traiter d'abord le muscle le plus faible"],"r":1,"e":"Le principe de causalité pose que la cause peut être anatomiquement éloignée du symptôme — d'où la nécessité d'un raisonnement clinique global.","s":2},{"q":"Les positions antalgiques adoptées spontanément par le patient :","o":["Résolvent le problème","Entraînent des altérations posturales avec des implications sur la fonction systémique","Sont sans conséquence","Doivent être encouragées"],"r":1,"e":"Elles évitent une douleur ou un blocage à court terme, mais installent des schémas qui aggravent le déséquilibre à plus long terme.","s":2},{"q":"Les muscles de la statique se caractérisent par des motoneurones alpha :","o":["Toniques, à décharge lente","Phasiques, à décharge rapide","Gamma uniquement","Sans particularité"],"r":0,"e":"Les muscles dynamiques ont au contraire des motoneurones alpha-phasiques à décharge rapide, adaptés aux contractions vigoureuses et brèves.","s":2},{"q":"Les muscles de la statique tirent leur énergie :","o":["De processus anaérobies","Du métabolisme aérobie","De la phosphocréatine","De la glycolyse rapide"],"r":1,"e":"Leurs contractions sont relativement lentes et ils sont peu fatigables — profil cohérent avec une sollicitation permanente.","s":2},{"q":"Les fibres musculaires des muscles statiques sont :","o":["Longues","Courtes","De longueur variable","Absentes"],"r":1,"e":"Les muscles dynamiques ont des fibres longues, adaptées au déplacement ; les statiques, riches en collagène, sont bâtis pour résister.","s":2},{"q":"La fonction statique de suspension est assurée notamment par :","o":["Le triceps sural et les ischio-jambiers","Les scalènes, le trapèze supérieur, les intercostaux et le système musculo-fibreux médiastinal","Les rotateurs internes et externes","Les adducteurs"],"r":1,"e":"La fonction d'érection antigravitaire revient au triceps sural, aux ischio-jambiers, aux pelvi-trochantériens, au droit fémoral et aux spinaux.","s":2},{"q":"La fonction de maintien des segments dans l'axe correct est assurée par :","o":["Les spinaux","Les rotateurs internes et externes, les adducteurs et abducteurs","Le diaphragme","Les intercostaux"],"r":1,"e":"Les muscles remplissant un rôle d'un degré de difficulté supérieur sont, selon le cours, plus volumineux, plus toniques et plus fibreux.","s":2},{"q":"Un muscle statique constamment sollicité tend :","o":["À l'allongement","Au raccourcissement et à la rigidité, faute de périodes de repos","À l'atrophie","À l'hypertrophie"],"r":1,"e":"Sa sollicitation est double : le tonus indispensable au maintien de la posture, et la contraction nécessaire aux mouvements.","s":2},{"q":"Selon la RPG, les muscles de la statique doivent être renforcés :","o":["De façon concentrique","Par contractions isométriques dans des positions progressivement excentriques","Par des mouvements rapides","Sans résistance"],"r":1,"e":"La méthode combine mouvement actif et étirement : renforcer sans raccourcir davantage est tout l'enjeu.","s":2},{"q":"Le « muscle vainqueur », dans le raisonnement RPG, est :","o":["Le plus fort en force maximale","Le plus raide","Le plus volumineux","Le plus douloureux"],"r":1,"e":"Le muscle qui cède est le « muscle vaincu ». La règle pratique qui en découle : on commence toujours par étirer le plus raccourci.","s":2},{"q":"La durée maximale d'une posture en RPG est de :","o":["10 minutes","20 minutes","30 minutes","60 minutes"],"r":2,"e":"Au-delà, le bénéfice ne progresse plus et la tolérance du patient se dégrade, ce qui compromet la qualité de la posture elle-même.","s":2},{"q":"La lenteur de la traction en RPG a pour but :","o":["D'augmenter la douleur tolérée","D'éviter le déclenchement du réflexe myotatique direct","De gagner du temps","De faciliter la contraction"],"r":1,"e":"Un étirement rapide activerait les fibres Ia et provoquerait une contraction réflexe du muscle que l'on cherche précisément à allonger.","s":2},{"q":"La RPG agit principalement sur les muscles où prédominent :","o":["Les fibres de type I","Les fibres de type IIa","Les fibres de type IIb","Toutes les fibres également"],"r":0,"e":"Ce sont elles qui assurent le maintien du contrôle postural, et qui composent majoritairement les muscles de la statique.","s":2},{"q":"Les niveaux d'intervention de la RPG comprennent :","o":["La prévention, le traitement et l'entretien","Le diagnostic et le traitement","La chirurgie et la rééducation","L'urgence et le suivi"],"r":0,"e":"Ses domaines couvrent le musculo-squelettique, le neuromusculaire et le cardio-respiratoire, à tous les âges de la vie.","s":2},{"q":"Les auto-postures en RPG sont :","o":["Improvisées par le patient","Déterminées et prescrites par le kinésithérapeute, après évaluation et apprentissage par le patient","Réservées aux sportifs","Interdites"],"r":1,"e":"Elles complètent les consultations individuelles où le kinésithérapeute intervient directement, et conditionnent la continuité du traitement.","s":2},{"q":"Le raccourcissement des muscles statiques entraîne, selon le cours :","o":["Une amélioration de la posture","Une altération de l'amplitude, de la qualité du mouvement, des altérations posturales et une symptomatologie","Un gain de force","Aucune conséquence"],"r":1,"e":"L'objectif de la méthode en découle directement : identifier et étirer les muscles responsables des signes et symptômes.","s":2},{"q":"Les muscles de la dynamique sont décrits comme :","o":["Très rouges et peu fatigables","Moins rouges, plus rosés, peu résistants et rapidement fatigables","Riches en collagène","À décharge lente"],"r":1,"e":"Leurs contractions sont dynamiques, rapides et vigoureuses, avec une énergie fournie par des processus anaérobies.","s":2},{"q":"Le principe de globalité impose :","o":["De traiter le corps humain comme un tout et d'identifier les implications des rétractions musculaires dans les pathologies","De traiter tous les patients de la même façon","De privilégier les exercices globaux","D'allonger la durée des séances"],"r":0,"e":"Il complète les principes d'individualité et de causalité, et fonde le recours à des étirements impliquant simultanément toute une chaîne.","s":2},{"q":"La RPG a été créée par Philippe Souchard en :","o":["1970/1971","1980/1981","1990/1991","2000/2001"],"r":1,"e":"Le cours la présente comme le fondement théorico-pratique de la rééducation posturale enseignée dans le module.","s":2},{"q":"Combien de vertèbres compte la colonne vertébrale au total ?","o":["33","24","26","31"],"r":0,"e":"7 cervicales, 12 thoraciques, 5 lombaires, 5 sacrées et 4 coccygiennes.","s":3},{"q":"Combien de vertèbres thoraciques compte la colonne ?","o":["12","7","5","4"],"r":0,"e":"Elles s'articulent avec les côtes et ont un rôle de protection.","s":3},{"q":"Quel segment rachidien supporte les charges les plus importantes ?","o":["Le segment lombaire","Le segment cervical","Le segment coccygien","Le segment thoracique"],"r":0,"e":"C'est le siège privilégié des lombalgies professionnelles.","s":3},{"q":"Combien de vertèbres sacrées, et sous quelle forme ?","o":["5, soudées","4, mobiles","7, soudées","5, mobiles"],"r":0,"e":"Le sacrum transmet les forces vers le bassin ; le coccyx compte 4 vertèbres.","s":3},{"q":"Quel est le rôle des courbures physiologiques du rachis ?","o":["Assurer l'amortissement des contraintes","Limiter la mobilité","Protéger la moelle uniquement","Augmenter la taille"],"r":0,"e":"Leur perte ou leur exagération augmente la charge discale et postérieure.","s":3},{"q":"Qu'est-ce qui définit une posture contraignante ?","o":["Une position maintenue, extrême ou asymétrique augmentant la charge musculo-squelettique","Toute position debout","Toute position assise","Une position tenue moins d'une minute"],"r":0,"e":"La durée de maintien est aussi importante que l'amplitude.","s":3},{"q":"Quel est le principe fondamental de l'ergonomie ?","o":["Adapter le travail à l'être humain","Adapter l'humain au travail","Augmenter les cadences de production","Standardiser tous les postes"],"r":0,"e":"Elle concilie santé/sécurité et efficacité du système de production.","s":3},{"q":"Que désigne la « tâche » en ergonomie ?","o":["Ce qui est prescrit : l'objectif et les conditions imposées par l'organisation","Ce que fait réellement le travailleur","La charge mentale","Le résultat obtenu"],"r":0,"e":"L'activité est ce qui est réellement fait pour atteindre l'objectif.","s":3},{"q":"Pourquoi l'écart tâche / activité est-il central en analyse ergonomique ?","o":["C'est dans cet écart que se logent les contraintes non prévues et donc les risques","Parce qu'il mesure la productivité","Parce qu'il définit le salaire","Parce qu'il n'a aucune importance pratique"],"r":0,"e":"L'activité tient compte des capacités réelles, de l'état du matériel et des aléas.","s":3},{"q":"Quel domaine de l'ergonomie traite de la charge mentale et des interfaces homme-machine ?","o":["L'ergonomie cognitive","L'ergonomie physique","L'ergonomie organisationnelle","L'anthropométrie"],"r":0,"e":"L'ergonomie physique traite postures, manutention et aménagement du poste.","s":3},{"q":"De quoi relève l'ergonomie organisationnelle ?","o":["Structures, horaires, travail en équipe, communication","Postures et manutention","Mémoire de travail et prise de décision","Éclairage et bruit"],"r":0,"e":"Elle porte sur l'organisation du travail plus que sur le poste lui-même.","s":3},{"q":"Dans quelle catégorie classe-t-on le bruit et les vibrations ?","o":["Facteurs de risque physiques","Facteurs chimiques","Facteurs biologiques","Facteurs psychosociaux"],"r":0,"e":"Les facteurs physiques incluent aussi températures extrêmes, rayonnements et éclairage inadéquat.","s":3},{"q":"Quels facteurs de risque sont majeurs dans les professions de santé ?","o":["Les facteurs biologiques","Les vibrations","Les rayonnements ionisants uniquement","Les températures extrêmes"],"r":0,"e":"Bactéries, virus, champignons et parasites.","s":3},{"q":"Le manque d'autonomie et le harcèlement relèvent de quels facteurs ?","o":["Psychosociaux","Physiques","Chimiques","Liés à l'activité"],"r":0,"e":"On y ajoute la charge de travail excessive, le faible soutien social et l'insécurité de l'emploi.","s":3},{"q":"Les gestes répétitifs et la manutention manuelle relèvent de quels facteurs ?","o":["Facteurs liés à l'activité","Facteurs physiques","Facteurs psychosociaux","Facteurs chimiques"],"r":0,"e":"On y inclut aussi les postures contraignantes et la station debout ou assise prolongée.","s":3},{"q":"Pourquoi une intervention centrée uniquement sur le geste échoue-t-elle souvent dans les TMS ?","o":["Parce que les TMS combinent répétitivité, force, posture et facteurs psychosociaux","Parce que le geste n'a aucune influence","Parce que les TMS sont uniquement génétiques","Parce que seule la force compte"],"r":0,"e":"Le stress et une faible latitude décisionnelle majorent l'incidence des TMS.","s":3},{"q":"Qu'est-ce qu'une maladie professionnelle ?","o":["Une affection figurant sur une liste officielle, au lien direct et déterminant avec une exposition","Une affection multifactorielle où le travail est un facteur parmi d'autres","Une affection préexistante majorée par le travail","Toute maladie survenant pendant les heures de travail"],"r":0,"e":"Elle ouvre droit à réparation sans avoir à prouver individuellement le lien causal.","s":3},{"q":"Qu'est-ce qu'une maladie liée au travail ?","o":["Une affection multifactorielle dont le travail est un facteur parmi d'autres","Une affection reconnue et listée officiellement","Une affection préexistante sans lien avec l'activité","Une maladie contagieuse contractée au travail"],"r":0,"e":"Il n'y a pas de reconnaissance automatique : l'enjeu est la prévention plutôt que la réparation.","s":3},{"q":"Qu'est-ce qu'une maladie aggravée par le travail ?","o":["Une affection préexistante, sans lien causal avec l'activité, mais majorée par les conditions de travail","Une maladie professionnelle reconnue","Une maladie multifactorielle","Une maladie liée à l'âge uniquement"],"r":0,"e":"Elle justifie des aménagements de poste et un suivi adapté.","s":3},{"q":"Quel est l'ordre des cinq niveaux de prévention ?","o":["Primordiale, primaire, secondaire, tertiaire, quaternaire","Primaire, secondaire, tertiaire, quaternaire, primordiale","Primordiale, secondaire, primaire, tertiaire, quaternaire","Primaire, primordiale, tertiaire, secondaire, quaternaire"],"r":0,"e":"La prévention primordiale vise à empêcher l'apparition même du facteur de risque.","s":3},{"q":"Que vise la prévention primordiale ?","o":["Empêcher l'apparition même du facteur de risque dans l'environnement","Dépister précocement la maladie","Limiter les séquelles","Éviter le surtraitement"],"r":0,"e":"Exemple : concevoir un poste qui n'introduit pas le risque, dès la conception.","s":3},{"q":"La substitution d'un produit dangereux relève de quel niveau de prévention ?","o":["Primaire","Primordiale","Secondaire","Tertiaire"],"r":0,"e":"La prévention primaire évite la survenue de la maladie chez des sujets sains exposés.","s":3},{"q":"Les examens périodiques et les audiométries relèvent de quel niveau ?","o":["Prévention secondaire","Prévention primaire","Prévention tertiaire","Prévention quaternaire"],"r":0,"e":"Il s'agit d'un dépistage précoce avant le stade symptomatique ou irréversible.","s":3},{"q":"Le reclassement professionnel et la reprise progressive relèvent de quel niveau ?","o":["Prévention tertiaire","Prévention secondaire","Prévention primaire","Prévention primordiale"],"r":0,"e":"La prévention tertiaire limite les séquelles et les incapacités d'une maladie installée.","s":3},{"q":"Que vise la prévention quaternaire ?","o":["Éviter le surdiagnostic, le surtraitement et la iatrogénie","Dépister précocement","Supprimer le risque à la source","Réadapter le travailleur"],"r":0,"e":"Elle protège de la médicalisation excessive et de la chronicisation par excès de soins.","s":3},{"q":"Quelle est la place de l'équipement de protection individuelle dans la hiérarchie des mesures ?","o":["Le dernier recours, après élimination, substitution, mesures techniques et organisationnelles","La première mesure à mettre en place","Une mesure équivalente à la substitution","Une mesure inutile"],"r":0,"e":"On privilégie toujours l'élimination du risque et les protections collectives.","s":3},{"q":"Quel est l'objectif de l'examen d'embauche ?","o":["Vérifier l'aptitude au poste, établir un état de référence et informer sur les risques","Dépister une maladie professionnelle installée","Réadapter le travailleur","Évaluer la productivité"],"r":0,"e":"Il a lieu avant l'affectation à un poste à risque.","s":3},{"q":"Dans quel cas réalise-t-on un examen occasionnel ?","o":["Reprise après absence prolongée, plainte, changement de poste ou grossesse","À intervalles réguliers fixés d'avance","Uniquement avant l'embauche","Uniquement au départ de l'entreprise"],"r":0,"e":"Il permet de réévaluer l'aptitude et d'adapter le poste.","s":3},{"q":"À partir de quel effectif un service interne de prévention est-il requis ?","o":["400 travailleurs","50 travailleurs","100 travailleurs","1 000 travailleurs"],"r":0,"e":"En deçà, ou faute de compétences internes, l'entreprise fait appel à un service externe agréé.","s":3},{"q":"Quelle approche est recommandée dans les lombalgies liées au travail ?","o":["La reprise précoce et progressive de l'activité","Le repos strict prolongé jusqu'à disparition de la douleur","L'arrêt définitif du poste","L'immobilisation par corset systématique"],"r":0,"e":"L'objectif est de restaurer la fonction et la confiance dans le mouvement, tout en agissant sur les contraintes du poste.","s":3},{"q":"Le segment rachidien le plus mobile, très sollicité par le travail sur écran, est :","o":["Le cervical","Le thoracique","Le lombaire","Le sacré"],"r":0,"e":"Le segment thoracique, articulé avec les côtes, a une mobilité réduite et un rôle de protection ; le lombaire supporte les charges les plus importantes.","s":3},{"q":"Le segment coccygien, avec ses 4 vertèbres, est décrit comme :","o":["Le principal support de charge","Vestigial, servant de point d'insertion musculo-ligamentaire","Le plus mobile","Absent chez l'adulte"],"r":1,"e":"Le segment sacré, formé de 5 vertèbres soudées, assure la transmission des forces vers le bassin. Le total est de 33 vertèbres.","s":3},{"q":"La perte ou l'exagération des courbures physiologiques sous l'effet de postures prolongées :","o":["Améliore l'amortissement","Augmente la charge sur les disques intervertébraux et les structures postérieures","Est sans conséquence","Renforce les muscles spinaux"],"r":1,"e":"Les courbures — lordose cervicale, cyphose thoracique, lordose lombaire — assurent l'amortissement des contraintes.","s":3},{"q":"Concernant la posture de travail, le cours souligne que :","o":["Seule l'amplitude compte","La durée de maintien est aussi importante que l'amplitude : une posture correcte maintenue trop longtemps devient délétère","Une posture correcte n'est jamais nocive","La durée n'a pas d'importance"],"r":1,"e":"C'est un point capital pour le conseil en entreprise : il n'existe pas de bonne posture, seulement une bonne alternance de postures.","s":3},{"q":"L'ergonomie cognitive traite notamment :","o":["Des postures et de la manutention","De la charge mentale, de la prise de décision, de la mémoire de travail et des interfaces homme-machine","Des horaires et du travail en équipe","De l'anthropométrie"],"r":1,"e":"L'ergonomie physique couvre postures, manutention et aménagement du poste ; l'organisationnelle les structures, horaires, communication et gestion de la qualité.","s":3},{"q":"Le bruit et les vibrations sont classés parmi les facteurs de risque :","o":["Physiques","Chimiques","Biologiques","Psychosociaux"],"r":0,"e":"S'y ajoutent les températures extrêmes, les rayonnements et un éclairage inadéquat.","s":3},{"q":"Le harcèlement et l'insécurité de l'emploi relèvent des facteurs de risque :","o":["Physiques","Chimiques","Psychosociaux","Liés à l'activité"],"r":2,"e":"Cette catégorie comprend aussi la charge de travail excessive, le manque d'autonomie, le faible soutien social et le conflit vie professionnelle-vie privée.","s":3},{"q":"Selon le cours, les troubles musculo-squelettiques résultent le plus souvent :","o":["D'un seul geste nocif","D'une combinaison de facteurs, la répétitivité, la force et la posture agissant en synergie","D'une prédisposition génétique","D'un traumatisme unique"],"r":1,"e":"Les facteurs psychosociaux, comme le stress et une faible latitude décisionnelle, en majorent l'incidence — d'où l'échec des interventions centrées sur le seul geste.","s":3},{"q":"Une maladie professionnelle se distingue par le fait que :","o":["Elle est multifactorielle","Elle figure sur une liste officielle, avec un lien direct reconnu, ouvrant réparation sans avoir à prouver individuellement la causalité","Elle préexistait à l'emploi","Elle n'ouvre aucun droit"],"r":1,"e":"La maladie liée au travail est multifactorielle et relève de la prévention plutôt que de la réparation ; la maladie aggravée par le travail préexistait.","s":3},{"q":"Une maladie aggravée par le travail justifie principalement :","o":["Une indemnisation automatique","Des aménagements de poste et un suivi adapté","Un licenciement pour inaptitude","Aucune mesure"],"r":1,"e":"Elle n'a pas de lien causal avec l'activité, mais les conditions de travail en majorent l'expression — ce qui appelle une adaptation, non une réparation.","s":3},{"q":"La prévention primordiale vise à :","o":["Dépister précocement","Empêcher l'apparition même du facteur de risque dans l'environnement","Limiter les séquelles","Éviter le surdiagnostic"],"r":1,"e":"Elle passe par la conception ergonomique en amont : un poste conçu sans introduire le risque n'aura jamais besoin de protection.","s":3},{"q":"La prévention quaternaire a pour objet :","o":["La vaccination","D'éviter le surdiagnostic et le surtraitement, et de protéger de la médicalisation excessive","Le reclassement professionnel","Le dépistage"],"r":1,"e":"Elle vise à éviter la iatrogénie et la chronicisation par excès de soins — enjeu majeur dans les lombalgies liées au travail.","s":3},{"q":"Dans la hiérarchie des mesures de prévention, l'équipement de protection individuelle est :","o":["La première réponse à privilégier","Le dernier recours","Équivalent aux mesures collectives","Sans utilité"],"r":1,"e":"L'ordre est : élimination du risque, substitution, mesures techniques et protections collectives, mesures organisationnelles, puis EPI.","s":3},{"q":"L'examen d'embauche a notamment pour objectif :","o":["De dépister une maladie installée","De vérifier l'aptitude au poste, d'établir un état de référence et d'informer sur les risques","De limiter les séquelles","D'évaluer le retour au travail"],"r":1,"e":"L'examen périodique relève de la prévention secondaire ; l'examen occasionnel réévalue l'aptitude lors d'un événement particulier.","s":3},{"q":"Un examen occasionnel est réalisé notamment :","o":["À intervalles réguliers","Lors d'une reprise après absence prolongée, d'une plainte, d'un changement de poste ou d'une grossesse","Avant l'affectation","Systématiquement chaque année"],"r":1,"e":"Son objet est de réévaluer l'aptitude et d'adapter le poste en fonction de la situation nouvelle.","s":3},{"q":"L'analyse des risques est décrite comme une démarche :","o":["Ponctuelle et facultative","Obligatoire, continue et documentée","Réservée aux grandes entreprises","Purement médicale"],"r":1,"e":"Elle enchaîne quatre temps : identifier les dangers, évaluer les risques, définir et hiérarchiser les mesures, évaluer leur efficacité.","s":3},{"q":"Parmi les interventions du kinésithérapeute en prévention primaire figurent :","o":["La formation aux gestes et postures, l'école du dos, les conseils d'aménagement et les pauses actives","La thérapie manuelle","Le reconditionnement à l'effort","L'éducation à la douleur"],"r":0,"e":"La thérapie manuelle et l'éducation à la douleur relèvent du traitement ; le reconditionnement à l'effort de la réinsertion.","s":3},{"q":"Dans l'axe réinsertion, le kinésithérapeute intervient notamment contre :","o":["La fatigue musculaire","La kinésiophobie, c'est-à-dire la peur du mouvement","L'absentéisme administratif","Le bruit au poste"],"r":1,"e":"S'y ajoutent le reconditionnement à l'effort, la restauration fonctionnelle du rachis et l'accompagnement de la reprise progressive.","s":3},{"q":"Le message clé du cours sur les lombalgies liées au travail est que :","o":["Le repos prolongé donne les meilleurs résultats","La reprise précoce et progressive de l'activité donne de meilleurs résultats que le repos prolongé","Il faut attendre la disparition complète de la douleur","L'arrêt de travail doit être maximal"],"r":1,"e":"L'objectif n'est pas d'attendre la fin de la douleur mais de restaurer la fonction et la confiance dans le mouvement, tout en agissant sur les contraintes du poste.","s":3},{"q":"L'évaluation ergonomique menée par le kinésithérapeute doit porter sur :","o":["La seule tâche prescrite","Les contraintes réelles, c'est-à-dire l'activité et non seulement la tâche","Les seuls antécédents du salarié","Les seules performances du poste"],"r":1,"e":"C'est dans l'écart entre le prescrit et le réel que se logent les contraintes non prévues, et donc les risques.","s":3},{"q":"Quelles sont les fausses articulations du complexe de l'épaule ?","o":["Sous-acromiale et scapulo-thoracique","Gléno-humérale et acromio-claviculaire","Sterno-costo-claviculaire et gléno-humérale","Acromio-claviculaire et scapulo-thoracique"],"r":0,"e":"Les vraies articulations sont la sterno-costo-claviculaire, l'acromio-claviculaire et la gléno-humérale.","s":4},{"q":"Quelle est l'amplitude d'élévation de la clavicule ?","o":["48°","15°","20°","50°"],"r":0,"e":"L'abaissement est de 15°, la protraction de 15-20°, la rétraction de 20-30°.","s":4},{"q":"Quelle rotation claviculaire est importante pour le rythme scapulo-huméral ?","o":["La rotation postérieure (50°)","La rotation antérieure (10°)","L'élévation","La protraction"],"r":0,"e":"La rotation postérieure atteint 50°, contre 10° pour la rotation antérieure.","s":4},{"q":"Qu'accompagne le mouvement d'élévation de la clavicule ?","o":["Un glissement inférieur de l'extrémité interne","Un glissement supérieur de l'extrémité interne","Un glissement antérieur","Aucun glissement"],"r":0,"e":"La protraction s'accompagne d'un glissement antérieur de l'extrémité interne.","s":4},{"q":"Quel muscle est le principal moteur de la protraction scapulaire ?","o":["Le dentelé antérieur","Le trapèze moyen","Les rhomboïdes","L'élévateur de la scapula"],"r":0,"e":"Sa faiblesse provoque une scapula alata ; le petit pectoral est accessoire.","s":4},{"q":"Quelle conséquence a la faiblesse du dentelé antérieur ?","o":["Une scapula alata","Une élévation permanente de l'épaule","Une rétraction scapulaire","Un abaissement de la clavicule"],"r":0,"e":"Le dentelé antérieur est essentiel à la protraction et à la rotation supérieure de la scapula.","s":4},{"q":"Quel mouvement scapulaire prévient le conflit sous-acromial ?","o":["La rotation supérieure","La rotation inférieure","La rétraction","L'abaissement"],"r":0,"e":"Elle est indispensable à l'abduction et à la flexion complètes de l'épaule.","s":4},{"q":"Quels muscles assurent la rotation supérieure de la scapula ?","o":["Trapèze supérieur et inférieur, et dentelé antérieur (fibres inférieures)","Rhomboïdes et élévateur de la scapula","Trapèze moyen seul","Petit pectoral seul"],"r":0,"e":"La rotation inférieure est assurée par les rhomboïdes, l'élévateur de la scapula et le trapèze moyen.","s":4},{"q":"Quel est le rôle de la rotation inférieure de la scapula ?","o":["Contrôler le retour en position neutre, notamment en excentrique","Élever le bras au-dessus de la tête","Stabiliser la scapula en poussée","Prévenir la scapula alata"],"r":0,"e":"Elle accompagne la descente du bras.","s":4},{"q":"Quels os composent l'articulation sterno-costo-claviculaire ?","o":["Extrémité médiale de la clavicule, manubrium sternal et 1ᵉʳ cartilage costal","Clavicule et acromion","Scapula et humérus","Clavicule et 2ᵉ côte"],"r":0,"e":"Un disque intra-articulaire assure congruence et stabilité.","s":4},{"q":"Où prend origine la capsule de l'articulation gléno-humérale ?","o":["Autour du col anatomique de l'humérus","Sur le trochiter","Sur le processus coracoïde","Sur l'acromion"],"r":0,"e":"Elle s'insère au niveau du labrum glénoïdien et du rebord de la cavité glénoïde.","s":4},{"q":"Quelle est la limite supérieure de l'articulation sous-acromiale ?","o":["Le ligament coraco-acromial","La tête de l'humérus","L'épine de la scapula","La clavicule"],"r":0,"e":"La limite inférieure est la tête de l'humérus.","s":4},{"q":"Quelle est la dimension de l'espace sous-acromial ?","o":["Environ 1 cm","Environ 3 cm","Environ 5 mm","Environ 2,5 mm"],"r":0,"e":"Sa limitation compromet la bourse sous-acromiale, la coiffe, la capsule et la longue portion du biceps.","s":4},{"q":"Quelle est la fonction principale de l'articulation sous-acromiale ?","o":["Protection supérieure de la tête humérale et facilitation du glissement du sus-épineux","Production de la rotation externe","Stabilisation antérieure","Transmission des charges axiales"],"r":0,"e":"Elle facilite le glissement entre le sus-épineux et le ligament coraco-acromial.","s":4},{"q":"Selon Bigliani et al. (1986), quel type d'acromion prédomine dans les ruptures complètes de coiffe ?","o":["Le type III (70 %)","Le type II (17 %)","Le type I (3 %)","Le type IV"],"r":0,"e":"Type III dans 70 %, type II dans 17 %, type I dans 3 %.","s":4},{"q":"Quel type d'acromion est le plus fréquent chez les patients souffrant de douleur d'épaule ?","o":["Le type II (curved), 62 %","Le type I (flat)","Le type III (hooked)","Le type IV (convex)"],"r":0,"e":"Sur 100 patients : type II 62 %, type I 21 %, type III 17 %.","s":4},{"q":"Où s'insère le ligament coraco-huméral ?","o":["Par deux faisceaux sur le trochiter et le trochin","Sur le labrum uniquement","Sur l'acromion","Sur la clavicule"],"r":0,"e":"Il prend origine sur le bord externe du processus coracoïde.","s":4},{"q":"Où s'insère le ligament gléno-huméral supérieur ?","o":["Sur le trochiter","Sur le trochin","Sur l'acromion","Sur le processus coracoïde"],"r":0,"e":"Les gléno-huméraux moyen et inférieur s'insèrent sur le trochin.","s":4},{"q":"De combien le labrum augmente-t-il la profondeur glénoïdienne ?","o":["D'environ 2,5 mm à 5 mm","De 1 cm","De 10 mm à 20 mm","Il ne l'augmente pas"],"r":0,"e":"Cela favorise l'emboîtement huméral.","s":4},{"q":"Qu'est-ce que le « chock-block effect » du labrum ?","o":["Un effet de butée mécanique face aux forces de translation humérale","Une compression négative intra-articulaire","Un renfort capsulaire","Un mécanisme proprioceptif"],"r":0,"e":"C'est le deuxième des quatre mécanismes de stabilisation du labrum.","s":4},{"q":"Quelle est la particularité de l'innervation du labrum ?","o":["Absence de mécanorécepteurs, seulement des terminaisons nerveuses libres","Forte densité de mécanorécepteurs","Absence totale d'innervation","Innervation exclusivement sympathique"],"r":0,"e":"Cela explique la faible douleur associée aux lésions labrales, malgré une instabilité significative.","s":4},{"q":"Quelle proportion de la longue portion du biceps est liée au labrum ?","o":["Environ 50 %","Environ 10 %","Environ 90 %","Aucune"],"r":0,"e":"C'est ce lien qui explique l'instabilité significative provoquée par les lésions labrales.","s":4},{"q":"Qu'est-ce qu'une lésion de Bankart ?","o":["Une désinsertion antéro-inférieure du labrum, typique des luxations","Une atteinte de l'origine de la longue portion du biceps","Une rupture du sus-épineux","Une fracture du trochiter"],"r":0,"e":"La lésion SLAP correspond à l'atteinte de l'origine de la longue portion du biceps.","s":4},{"q":"Entre quels muscles passe l'artère subclavière avec le plexus brachial ?","o":["Entre le scalène antérieur et le scalène moyen","Entre le petit et le grand pectoral uniquement","Entre le trapèze et le rhomboïde","Entre le deltoïde et le supra-épineux"],"r":0,"e":"Elle passe ensuite sous la clavicule et entre les pectoraux jusqu'à l'aisselle, où elle devient artère axillaire.","s":4},{"q":"Quel nerf innerve l'articulation acromio-claviculaire ?","o":["Le nerf suprascapulaire (C5-C6) et le nerf pectoral","Le nerf circonflexe seul","Le nerf subclavier","Le nerf musculo-cutané"],"r":0,"e":"La gléno-humérale est innervée par les nerfs pectoral, supra-scapulaire et circonflexe.","s":4},{"q":"Quel muscle initie l'abduction de 0° à 15° ?","o":["Le supra-épineux","Le deltoïde moyen","L'infra-épineux","Le subscapulaire"],"r":0,"e":"Le deltoïde moyen prend le relais de 15° à 90° ; le supra-épineux est aussi stabilisateur supérieur.","s":4},{"q":"Quel muscle est le stabilisateur antérieur de la tête humérale ?","o":["Le subscapulaire","L'infra-épineux","Le petit rond","Le triceps (longue portion)"],"r":0,"e":"L'infra-épineux et le petit rond sont stabilisateurs postérieurs.","s":4},{"q":"Selon Hik & Ackland (2019), quels muscles ont les plus grands bras de levier d'élévation humérale ?","o":["Les faisceaux antérieur et moyen du deltoïde","Le grand pectoral et le grand dorsal","Les muscles de la coiffe","Le triceps brachial"],"r":0,"e":"Le grand pectoral, le grand dorsal et le grand rond agissent comme principaux abaisseurs.","s":4},{"q":"Quelles sont les trois composantes du stiffness musculaire ?","o":["Propriétés mécaniques intrinsèques, activation neuromusculaire et impact fonctionnel","Force, endurance et souplesse","Viscosité, élasticité et plasticité","Tonus, tension et rigidité"],"r":0,"e":"Le stiffness est la résistance viscoélastique et neuromusculaire à la déformation ou à l'allongement.","s":4},{"q":"Quelle est la différence entre feedforward et feedback ?","o":["Le feedforward est une planification anticipée rapide mais moins adaptable, le feedback une correction en temps réel plus lente mais plus précise","Le feedback précède le mouvement","Le feedforward utilise l'information sensorielle en temps réel","Ils sont équivalents"],"r":0,"e":"La copie efférente est envoyée au lobule pariétal supérieur et au cervelet pour comparer l'attendu et le réalisé.","s":4},{"q":"L'amplitude de rétraction claviculaire est de :","o":["10°","15 à 20°","20 à 30°","48°"],"r":2,"e":"Repères claviculaires : élévation 48°, abaissement 15°, protraction 15 à 20°, rétraction 20 à 30°, rotation antérieure 10°, rotation postérieure 50°.","s":4},{"q":"L'élévation de la clavicule s'accompagne :","o":["D'un glissement supérieur de l'extrémité interne","D'un glissement inférieur de l'extrémité interne","D'un glissement antérieur","D'aucun glissement"],"r":1,"e":"C'est le principe du bras de levier autour de l'articulation sterno-costo-claviculaire : le déplacement latéral et le déplacement médial sont inversés.","s":4},{"q":"La protraction claviculaire s'accompagne :","o":["D'un glissement antérieur de l'extrémité interne","D'un glissement postérieur de l'extrémité interne","D'une rotation","D'aucun mouvement associé"],"r":1,"e":"Et inversement pour la rétraction. Ces couplages conditionnent les techniques de mobilisation de l'articulation sterno-costo-claviculaire.","s":4},{"q":"L'élévation scapulaire est assurée par :","o":["Le trapèze supérieur, l'élévateur de la scapula et, en auxiliaires, les rhomboïdes","Le trapèze inférieur et le petit pectoral","Le dentelé antérieur","Le trapèze moyen"],"r":0,"e":"Elle maintient l'épaule élevée, soutient le poids en suspension et participe à la posture érigée.","s":4},{"q":"L'abaissement scapulaire fait intervenir :","o":["Le trapèze supérieur","Le trapèze inférieur, le petit pectoral et la portion inférieure du dentelé antérieur","Les rhomboïdes","L'élévateur de la scapula"],"r":1,"e":"Il stabilise la scapula lors des mouvements de poussée vers le bas, comme lors d'un transfert en appui sur les mains.","s":4},{"q":"La rétraction scapulaire est assurée par :","o":["Le dentelé antérieur et le petit pectoral","Le trapèze moyen et les rhomboïdes","Le trapèze inférieur","Le petit rond"],"r":1,"e":"Elle intervient dans les mouvements de tirage et joue un rôle important dans la posture et la stabilité scapulaire.","s":4},{"q":"La rotation inférieure de la scapula est assurée par :","o":["Le trapèze supérieur et inférieur avec le dentelé antérieur","Les rhomboïdes, l'élévateur de la scapula et le trapèze moyen","Le petit pectoral seul","Le grand dorsal"],"r":1,"e":"Elle contrôle le retour de la scapula en position neutre et joue un rôle important dans le contrôle excentrique.","s":4},{"q":"L'articulation sterno-costo-claviculaire comporte :","o":["Un ménisque latéral","Un disque intra-articulaire assurant congruence et stabilité","Aucune structure intermédiaire","Un labrum"],"r":1,"e":"Elle unit l'extrémité médiale de la clavicule, la face supérieure du manubrium sternal et l'extrémité médiale du premier cartilage costal.","s":4},{"q":"La capsule gléno-humérale s'insère :","o":["Sur le col chirurgical de l'humérus","Au niveau du labrum glénoïdien et du rebord de la cavité glénoïde","Sur l'acromion","Sur le processus coracoïde"],"r":1,"e":"Elle prend origine autour du col anatomique de l'humérus. Les surfaces sont revêtues de cartilage hyalin : tête convexe contre glène concave.","s":4},{"q":"La limite inférieure de l'articulation sous-acromiale est :","o":["Le ligament coraco-acromial","La tête de l'humérus","L'acromion","Le tendon du supra-épineux"],"r":1,"e":"Sa limite supérieure est le ligament coraco-acromial. Sa fonction principale est la protection supérieure de la tête humérale.","s":4},{"q":"Dans l'étude de Bigliani et al. (1986) sur les ruptures complètes de coiffe, l'acromion de type III était retrouvé dans :","o":["3 % des cas","17 % des cas","70 % des cas","100 % des cas"],"r":2,"e":"Le type II l'était dans 17 % des cas et le type I dans 3 %, ce qui a établi le lien entre morphologie acromiale crochue et rupture de la coiffe.","s":4},{"q":"Chez 100 patients souffrant de douleur d'épaule, le type acromial le plus fréquent était :","o":["Le type I, plat, à 21 %","Le type II, courbe, à 62 %","Le type III, crochu, à 17 %","Le type IV, convexe"],"r":1,"e":"Sur 292 scapulas, la répartition était de 56,5 % de type II, 28,8 % de type III et 12,1 % de type I.","s":4},{"q":"Le type IV acromial, convexe, a été retrouvé sur 423 scapulas sèches dans :","o":["2,6 % des cas","12 % des cas","28 % des cas","56 % des cas"],"r":0,"e":"C'est la morphologie la plus rare, ce qui explique qu'elle soit peu documentée dans les séries cliniques.","s":4},{"q":"Chez les patients présentant des ruptures transfixiantes, le type III était retrouvé dans :","o":["13 % des cas, comme dans la population contrôle","39,6 % des cas","62 % des cas, contre 13 % dans la population contrôle","24,2 % des cas"],"r":2,"e":"Ce contraste avec la population contrôle est l'argument le plus fort en faveur d'un rôle causal de la morphologie acromiale.","s":4},{"q":"Le labrum augmente la profondeur glénoïdienne d'environ :","o":["1 mm à 2 mm","2,5 mm à 5 mm","5 mm à 10 mm","10 mm à 15 mm"],"r":1,"e":"Il double donc approximativement la profondeur de la cavité, ce qui contribue significativement à la stabilité d'une articulation très peu contrainte.","s":4},{"q":"Concernant l'innervation du labrum, le cours précise qu'il :","o":["Est riche en mécanorécepteurs","N'a pas de mécanorécepteurs, seulement des terminaisons nerveuses libres","Est totalement dépourvu d'innervation","Contient des fuseaux neuromusculaires"],"r":1,"e":"Cela limite son rôle proprioceptif direct, mais explique qu'une lésion labrale puisse être douloureuse.","s":4},{"q":"Le ligament coraco-huméral prend origine :","o":["Sur le bord externe du processus coracoïde","Sur l'acromion","Sur la glène","Sur le col chirurgical"],"r":0,"e":"Il participe, avec la capsule et son renfort antéro-inférieur, à la stabilité passive de l'articulation gléno-humérale.","s":4},{"q":"Le contrôle en feedforward, appliqué à l'épaule, se caractérise par :","o":["Une correction pendant l'exécution, lente mais précise","Une anticipation, rapide mais moins adaptable","Une absence de contrôle","Un contrôle purement réflexe"],"r":1,"e":"Le feedback, à l'inverse, corrige pendant l'exécution : il est plus lent mais plus précis. Les deux modes se complètent.","s":4},{"q":"La rotation postérieure de la clavicule, d'une amplitude de 50°, est importante pour :","o":["La protraction scapulaire","Le rythme scapulo-huméral","L'abaissement de l'épaule","La stabilité sterno-claviculaire"],"r":1,"e":"Sans elle, la scapula ne peut accomplir sa rotation supérieure complète, et l'élévation du bras reste limitée.","s":4},{"q":"Les rôles du complexe de l'épaule énumérés par le cours comprennent :","o":["Chaîne cinétique, support opérationnel et équilibre entre stabilité et fonctionnalité","Uniquement la mobilité","Uniquement la stabilité","La seule protection nerveuse"],"r":0,"e":"Cette tension entre stabilité et fonctionnalité est la caractéristique de l'épaule : l'articulation la plus mobile du corps est aussi la moins contrainte.","s":4},{"q":"Quelle est la fonction primaire du complexe lombo-pelvien ?","o":["Transférer les charges","Produire la force musculaire maximale","Protéger la moelle épinière","Permettre la rotation du tronc"],"r":0,"e":"La meilleure stratégie assure transfert de charge, contrôle de la rotation et translation, alignement optimal et équilibre.","s":5},{"q":"Que ne doit PAS faire une bonne stratégie de stabilisation ?","o":["Augmenter la pression intra-abdominale ou créer du stress articulaire","Maintenir le schéma respiratoire","Contrôler la rotation","Assurer l'alignement"],"r":0,"e":"Elle doit au contraire maintenir le schéma respiratoire (Lee, 2011).","s":5},{"q":"Comment définit-on la stabilité dynamique ?","o":["La capacité du système à résister et contrôler le mouvement dans toute l'amplitude disponible","La capacité à rester immobile","La force maximale des muscles du tronc","L'amplitude articulaire disponible"],"r":0,"e":"Elle dépend des sous-systèmes passif, actif, neural et émotionnel.","s":5},{"q":"Quel sous-système est constitué des tissus inertes ?","o":["Le sous-système passif","Le sous-système actif","Le sous-système neural","Le sous-système émotionnel"],"r":0,"e":"Il assure la stabilité articulaire passive.","s":5},{"q":"Quel est le rôle du sous-système émotionnel ?","o":["Le stress, l'anxiété et la peur affectent la capacité du contrôle moteur à agir efficacement","Il produit la force musculaire","Il assure la proprioception","Il n'a aucun impact démontré"],"r":0,"e":"L'état émotionnel est fondamental pour la santé et la récupération (Holstege).","s":5},{"q":"Que se passe-t-il quand la stabilité d'un sous-système diminue ?","o":["Un autre système compense, avec une altération excessive et anormale du mouvement","Le mouvement s'arrête","La douleur disparaît","Le système passif se renforce"],"r":0,"e":"Tropp et al. (1993) : la compensation se fait sans contrôle musculaire adéquat.","s":5},{"q":"Que devient le multifidus quand la colonne lombaire reste longtemps en flexion ?","o":["Il se « turn off »","Il s'hypertrophie","Il devient hyperactif","Il n'est pas affecté"],"r":0,"e":"Richardson et al. (2004) ; Williams et al. (2000) montrent des altérations du schéma d'activation.","s":5},{"q":"Qu'est-ce que la zone neutre ?","o":["La zone proche de la position neutre où les structures ostéo-ligamentaires offrent le minimum de résistance","La zone de fin d'amplitude","L'amplitude totale de mouvement","La zone où la douleur apparaît"],"r":0,"e":"La zone élastique va de la fin de la zone neutre à la fin de l'amplitude physiologique (Panjabi, 1992).","s":5},{"q":"Qu'est-ce que la pars interarticularis ?","o":["La partie de la vertèbre entre les processus articulaires supérieur et inférieur","Le disque intervertébral","Le ligament jaune","L'apophyse épineuse"],"r":0,"e":"Elle contribue à la stabilité de la colonne vertébrale.","s":5},{"q":"Qui a proposé la classification des muscles en systèmes local et global ?","o":["Bergmark (1989)","Panjabi (1992)","Comerford & Mottram (2001)","Lee (2004)"],"r":0,"e":"Local = stabilité segmentaire ou intra-pelvienne ; global = stabilité régionale.","s":5},{"q":"Quelle est la caractéristique des stabilisateurs locaux ?","o":["Mono-articulaires et profonds","Poly-articulaires et superficiels","Mono-articulaires et superficiels","Poly-articulaires et profonds"],"r":0,"e":"Les stabilisateurs globaux sont mono-articulaires superficiels, les mobilisateurs globaux poly-articulaires.","s":5},{"q":"Quel type de contraction caractérise les stabilisateurs locaux ?","o":["Tonique isométrique, constante et indépendante de la direction","Tonique excentrique dépendante de la direction","Phasique concentrique","Balistique"],"r":0,"e":"Les stabilisateurs globaux ont une contraction tonique excentrique, les mobilisateurs une contraction phasique concentrique.","s":5},{"q":"Quel muscle appartient aux stabilisateurs locaux ?","o":["Le transverse de l'abdomen","Le droit de l'abdomen","Le grand dorsal","Les ischio-jambiers"],"r":0,"e":"Système local : transverse de l'abdomen, multifidus, diaphragme, plancher pelvien, psoas (fibres postérieures).","s":5},{"q":"Quel muscle est un mobilisateur global ?","o":["Le grand dorsal","Le multifidus","Le moyen fessier","Le transverse de l'abdomen"],"r":0,"e":"Mobilisateurs globaux : droit de l'abdomen, grand dorsal, ischio-jambiers, piriforme.","s":5},{"q":"Comment se définit le core ?","o":["La zone comprise entre le diaphragme et le plancher pelvien","La seule région lombaire","Les abdominaux superficiels","Le bassin osseux"],"r":0,"e":"Il inclut la zone inférieure de la colonne dorsale, la colonne lombaire et la zone du bassin.","s":5},{"q":"Quand les muscles du système local doivent-ils stabiliser les articulations ?","o":["AVANT qu'elles ne soient soumises à des charges additionnelles","Pendant la charge uniquement","Après la charge","Uniquement au repos"],"r":0,"e":"C'est la définition de la stabilité du core selon Leetun et al. (2004).","s":5},{"q":"Qu'est-ce que la form closure ?","o":["La forme, la structure et l'orientation articulaire qui favorisent la stabilité","Les forces compressives apportées par les muscles et fascias","La pression intra-abdominale","La rigidité articulaire par co-contraction"],"r":0,"e":"La force closure correspond aux forces compressives apportées par ligaments, muscles et fascias.","s":5},{"q":"Qu'apporte la force closure ?","o":["Un mécanisme d'auto-verrouillage articulaire augmentant la rigidité segmentaire","La forme des surfaces articulaires","La mobilité maximale","La souplesse ligamentaire"],"r":0,"e":"Elle augmente le contrôle segmentaire, améliore la distribution de charge et diminue le stress des structures passives.","s":5},{"q":"Quels sont les trois mécanismes de la stabilité du core ?","o":["Pression intra-abdominale, tension du fascia thoraco-lombaire et rigidité articulaire","Force, endurance et souplesse","Mobilité, stabilité et coordination","Feedback, feedforward et proprioception"],"r":0,"e":"Ce sont les trois mécanismes décrits dans le cours.","s":5},{"q":"Quels muscles génèrent la pression intra-abdominale ?","o":["Le diaphragme, le plancher pelvien et le transverse de l'abdomen","Le droit de l'abdomen et les obliques","Le grand dorsal et le carré des lombes","Les ischio-jambiers et les fessiers"],"r":0,"e":"Leur contraction coordonnée augmente directement la rigidité physiologique vertébrale (Hodges et al., 1999).","s":5},{"q":"Quels mécanorécepteurs contient le fascia thoraco-lombaire ?","o":["Les corpuscules de Ruffini et de Pacini","Les fuseaux neuromusculaires","Les organes tendineux de Golgi","Les corpuscules de Meissner"],"r":0,"e":"Il s'étend du bassin jusqu'au crâne et couvre les muscles profonds de la colonne (Norris, 2008).","s":5},{"q":"Que se passe-t-il si le transverse de l'abdomen développe une tension d'un seul côté ?","o":["Un déplacement peut survenir","Le mouvement est limité","La stabilité augmente","Rien ne change"],"r":0,"e":"Si la tension est égale des deux côtés, le mouvement sera limité (Richardson et al., 2004).","s":5},{"q":"Quand le diaphragme s'active-t-il lors d'une flexion rapide de l'épaule ?","o":["En même temps que le transverse, environ 20 ms avant l'activité EMG du deltoïde","Après le deltoïde","20 s avant le mouvement","Il ne s'active pas"],"r":0,"e":"C'est un ajustement postural anticipatoire décrit par Hodges.","s":5},{"q":"Comment le plancher pelvien répond-il à une contraction abdominale forte ?","o":["Toute sa musculature se contracte","Il se relâche","Il ne réagit pas","Il se contracte seulement d'un côté"],"r":0,"e":"Lors d'un recrutement abdominal sélectif et doux, il répond par une réaction spécifique (Sapsford et al., 2001).","s":5},{"q":"Comment définit-on l'instabilité vertébrale ?","o":["L'incapacité de maintenir un displacement sous charge sans symptomatologie neurologique, douleur ou déformation","Une hypermobilité articulaire isolée","Une faiblesse musculaire du tronc","Une perte d'amplitude"],"r":0,"e":"Définition de White, Panjabi et al. (1990).","s":5},{"q":"Quel signe caractérise les mouvements répétés sans contrôle ?","o":["Perte bilatérale de la contraction anticipatoire du multifidus","Hyperactivité du transverse","Raccourcissement du psoas","Augmentation de la rigidité segmentaire"],"r":0,"e":"On note aussi un retard du grand fessier et une activation anticipée des ischio-jambiers du côté symptomatique.","s":5},{"q":"Comment les stabilisateurs locaux réagissent-ils à la douleur ?","o":["Par l'inhibition","Par des spasmes","Par une hyperactivité","Par un raccourcissement"],"r":0,"e":"Les mobilisateurs globaux réagissent par des spasmes ; les globaux par un recrutement tonique insuffisant.","s":5},{"q":"La récupération de la dysfonction est-elle spontanée après disparition de la douleur ?","o":["Non, la douleur peut disparaître mais la dysfonction persiste","Oui, systématiquement","Oui, si la douleur dure moins de 6 semaines","Seulement chez les sportifs"],"r":0,"e":"Ces dysfonctions sont réversibles par l'application de stimuli adéquats à leur fonction (Hides et al., 1996).","s":5},{"q":"Quelle posture se caractérise par des abdominaux déconnectés et une compensation en extension ?","o":["La posture cypho-lordotique","Le sway back","Le dos plat","La posture neutre"],"r":0,"e":"Le sway back donne une compensation en flexion avec obliques, multifidus et fessiers déconnectés.","s":5},{"q":"Quel sling est composé du grand dorsal, du fascia thoraco-lombaire et du grand fessier controlatéral ?","o":["Le sling oblique postérieur","Le sling longitudinal profond","Le sling oblique antérieur","Le sling latéral"],"r":0,"e":"Il favorise l'efficience de l'extension, le contrôle lombo-pelvien et le contrôle des rotations.","s":5},{"q":"Selon Lee (2011), la meilleure stratégie de stabilisation assure :","o":["Un transfert de charge, le contrôle de la rotation et de la translation, un alignement optimal et l'équilibre","La seule rigidité du tronc","Une contraction maximale permanente","L'immobilisation du rachis"],"r":0,"e":"La stratégie ne doit créer de stress dans aucune articulation, ni augmenter la pression intra-abdominale de façon inadaptée, et doit maintenir le schéma respiratoire.","s":5},{"q":"Parmi les éléments que la stratégie de stabilisation doit maintenir (Lee, 2004), le cours cite :","o":["L'interprétation appropriée des stimuli afférents avec une réponse motrice adéquate","La force maximale des abdominaux","Une apnée contrôlée","Une immobilité complète"],"r":0,"e":"S'y ajoutent l'intégrité des structures, la capacité de contraction prolongée et coordonnée, la compression articulaire adéquate et le contrôle neural.","s":5},{"q":"Selon Saal et Saal (1989), sont fondamentaux en stabilisation :","o":["La force maximale des abdominaux","La vitesse de réaction des muscles abdominaux aux forces déplaçantes et la capacité à dissocier la musculature abdominale profonde","L'endurance des spinaux uniquement","L'amplitude lombaire"],"r":1,"e":"Le délai de réaction compte davantage que la force brute : un muscle puissant qui se contracte trop tard ne protège pas l'articulation.","s":5},{"q":"La stabilité dynamique se définit comme :","o":["L'immobilité du rachis","La capacité du ou des systèmes à résister et contrôler le mouvement dans toute l'amplitude disponible","La force maximale développée","La rigidité passive"],"r":1,"e":"Elle repose sur quatre sous-systèmes selon Panjabi : passif, actif, neural et émotionnel.","s":5},{"q":"Le sous-système neural, dans le modèle de Panjabi, comprend :","o":["Les tissus inertes","Les tissus contractiles","Les nerfs, les terminaisons proprioceptives et le système nerveux central","Les émotions"],"r":2,"e":"Il assure le feedback de surveillance de l'information et la modulation de la réponse — c'est le chef d'orchestre du système.","s":5},{"q":"Le sous-système émotionnel, selon Holstege, influence la stabilité parce que :","o":["Le stress, l'anxiété et la peur affectent la capacité du contrôle moteur à agir efficacement","Il modifie la structure osseuse","Il augmente la force musculaire","Il n'a qu'un rôle marginal"],"r":0,"e":"Le cours précise que l'état émotionnel est fondamental pour la santé et la récupération : ce n'est pas un facteur annexe mais un sous-système à part entière.","s":5},{"q":"Selon Tropp et ses collaborateurs (1993), lorsque la stabilité d'un sous-système diminue :","o":["Le mouvement s'arrête","Un autre système compense, avec une altération excessive et anormale du mouvement sans contrôle musculaire","La douleur disparaît","La stabilité globale augmente"],"r":1,"e":"La compensation masque le déficit initial tout en produisant des contraintes nouvelles : c'est le mécanisme de nombreuses récidives.","s":5},{"q":"O'Sullivan (2002) a montré que les stabilisateurs lombo-pelviens sont :","o":["Plus actifs en postures passives","Actifs en postures érigées dans un alignement optimal, et moins actifs en slump sitting ou sway standing","Toujours également actifs","Inactifs en position debout"],"r":1,"e":"C'est un argument direct en faveur de l'éducation posturale : la posture affaissée désactive précisément les muscles qui protègent le rachis.","s":5},{"q":"Richardson et ses collaborateurs (2004) ont montré que le multifidus :","o":["S'hypertrophie en flexion prolongée","Se « turn off » quand la colonne lombaire reste longtemps en flexion","Est indépendant de la position","Ne participe pas à la stabilité"],"r":1,"e":"Williams et ses collaborateurs (2000) avaient montré que le maintien en flexion altère le schéma d'activation de ce muscle.","s":5},{"q":"La zone neutre se définit comme :","o":["L'ensemble de l'amplitude physiologique","Une petite zone proche de la position neutre où les structures ostéo-ligamentaires offrent le minimum de résistance","La fin d'amplitude","La zone de blocage"],"r":1,"e":"La zone élastique s'étend de la fin de la zone neutre à la fin de l'amplitude physiologique, où le système passif limite et contrôle (Panjabi, 1992).","s":5},{"q":"La pars interarticularis est la partie de la vertèbre située :","o":["Entre les processus articulaires supérieur et inférieur de la facette","Entre le corps et l'arc postérieur","Au sommet du processus épineux","Dans le foramen"],"r":0,"e":"Elle contribue à la stabilité de la colonne, et sa fracture de fatigue constitue la spondylolyse, fréquente chez le sportif jeune.","s":5},{"q":"Les ajustements posturaux anticipatoires supposent que les stabilisateurs :","o":["Réagissent après le mouvement","Se contractent pour préparer le système à la force imminente","Restent passifs","Se relâchent avant l'effort"],"r":1,"e":"Leur retard ou leur absence est l'une des anomalies les mieux documentées dans la lombalgie chronique.","s":5},{"q":"La douleur, dans le contrôle de la stabilité lombaire :","o":["Améliore la contraction musculaire","Peut inhiber la contraction musculaire et affecter l'alignement par les postures antalgiques","Est sans effet moteur","Renforce l'alignement"],"r":1,"e":"Les postures antalgiques renforcent alors le mauvais alignement, ce qui crée un cercle d'entretien entre douleur et dysfonction.","s":5},{"q":"Bergmark (1989) distingue le système local, essentiel à :","o":["La stabilité segmentaire ou intra-pelvienne","La stabilité régionale","Le contrôle de l'orientation du thorax","Le mouvement des membres"],"r":0,"e":"Le système global assure la stabilité régionale et contrôle l'orientation du thorax par rapport au bassin, ou des membres par rapport au tronc.","s":5},{"q":"Le form closure désigne :","o":["Les forces compressives apportées par les ligaments, muscles et fascias","La forme, la structure et l'orientation articulaire","La pression intra-abdominale","La tension du fascia thoraco-lombaire"],"r":1,"e":"Le force closure correspond aux forces compressives actives. La stabilité résulte de la combinaison des deux.","s":5},{"q":"La stabilité du core résulte, selon le cours, de :","o":["L'augmentation de la pression intra-abdominale, de la tension du fascia thoraco-lombaire et de la rigidité articulaire","La seule contraction du transverse","La seule force des spinaux","La rigidité passive des ligaments"],"r":0,"e":"Ces trois mécanismes agissent simultanément : aucun ne suffit isolément à assurer le transfert de charge.","s":5},{"q":"La fonction primaire du complexe lombo-pelvien est :","o":["De produire le mouvement","De transférer les charges","De protéger la moelle","De permettre la respiration"],"r":1,"e":"Tout le reste en découle : contrôle du mouvement, alignement, équilibre et protection des organes s'ordonnent autour de cette fonction.","s":5},{"q":"Parmi les objectifs de la stabilisation lombo-pelvienne, le cours cite :","o":["Réaliser tout mouvement avec le contrôle nécessaire, éviter les lésions à court et long terme, et protéger les organes","Maximiser la force","Limiter toute mobilité","Augmenter l'amplitude"],"r":0,"e":"La sécurité du mouvement, et non son amplitude ou sa puissance, est le critère retenu pour juger d'une bonne stratégie.","s":5},{"q":"Le sous-système passif correspond :","o":["Aux tissus contractiles","Aux tissus inertes assurant la stabilité articulaire passive","Au système nerveux","À l'état émotionnel"],"r":1,"e":"Il limite et contrôle la fin de l'amplitude disponible, dans la zone élastique, mais offre peu de résistance dans la zone neutre.","s":5},{"q":"La stratégie de stabilisation, selon le cours, ne doit pas :","o":["Maintenir le schéma respiratoire","Créer de stress dans les articulations ni augmenter indûment la pression intra-abdominale","Contrôler le mouvement","Assurer l'alignement"],"r":1,"e":"Une stratégie qui rigidifie en bloquant la respiration protège peut-être le segment visé, mais au prix de contraintes reportées ailleurs.","s":5}]};
